/// Exhaustive: every variant has a non-empty upper-snake-case
/// `to_python_name`. Catches silent regenerations that drop
/// variants and pins the format.
#[test]
fn every_variant_has_python_name() {
    for &id in RelicId::all() {
        let name = id.to_python_name();
        assert!(!name.is_empty(), "empty python_name for {id:?}");
        assert!(
            name.bytes()
                .all(|b| b == b'_' || b.is_ascii_uppercase() || b.is_ascii_digit()),
            "non upper-snake-case python_name for {id:?}: {name:?}"
        );
    }
    assert_eq!(RelicId::BurningBlood.to_python_name(), "BURNING_BLOOD");
    assert_eq!(RelicId::CrackedCore.to_python_name(), "CRACKED_CORE");
    assert_eq!(
        RelicId::RingOfTheSnake.to_python_name(),
        "RING_OF_THE_SNAKE"
    );
    assert_eq!(RelicId::DivineRight.to_python_name(), "DIVINE_RIGHT");
}

/// `RelicId` variant count matches the Python pin plus the
/// C#-only extras (sanity guard).
#[test]
fn relic_id_variant_count_is_stable() {
    // Python `sts2_env/relics/base.py::RelicId` had 289 members at the
    // (now archived) pin `01c094d`, plus the C#-only relics appended
    // since: NEOWS_TALISMAN / WINGED_BOOTS / PHIAL_HOLSTER (bead
    // `sts2-rs-4rwv4`, W9a-c) + NEOWS_BONES (bead `sts2-rs-wjuoi`,
    // W9e) + HEFTY_TABLET (bead `sts2-rs-w6hdj`, W9d) + the three
    // v0.107.1 Ancient/Neow relics FISHING_ROD / KALEIDOSCOPE /
    // SILKEN_TRESS (bead `sts2-rs-v0107-content-port-wb8lk.6`).
    // `relic_ids_generated.rs` is hand-maintained against the v0.107.1 C#
    // decompilation — bump this count in the same change that adds or
    // removes a variant. This assertion is the only guard.
    assert_eq!(RelicId::all().len(), 289 + 5 + 3);
}

