// --- should_die_late — bead `sts2-rs-p62n0` ---------------------

/// Listener that heals the player to 30 HP and votes prevent.
/// Stands in for LizardTail's canonical behaviour without
/// requiring the full per-relic state plumbing (that lives in
/// `y7795`'s body-fill once it's unblocked).
fn h_should_die_late_heal_and_prevent(state: &mut CombatState) -> EffectResult {
    state.player.current_hp = 30;
    EffectResult::Resolved
}

/// Listener that abstains — neither mutates nor votes.
fn h_should_die_late_abstain(_state: &mut CombatState) -> EffectResult {
    EffectResult::NotImplemented
}

/// Pin the prevent-and-heal path through the listener directly.
/// Avoids asserting on the global dispatcher's tally because the
/// channel registry is a process-global static and sibling
/// integration tests in `combat_loop` may also register a
/// `LizardTail` listener (which would invalidate any
/// "abstain-only ⇒ false" claim under cargo's non-deterministic
/// test order). What we DO pin: (a) the abstain listener is
/// HP-neutral and (b) the prevent listener heals + votes
/// Resolved when invoked directly. End-to-end "Resolved vote
/// flips the dispatcher and the combat-loop skips the flip"
/// lives in `combat_loop::tests::check_combat_end_prevented_by_should_die_late_listener`.
#[test]
#[serial_test::serial(global_registry)]
fn should_die_late_listener_contracts() {
    let mut state = CombatState::default();
    state.player.current_hp = 0;

    // Abstain: NotImplemented + HP untouched.
    let r = h_should_die_late_abstain(&mut state);
    assert_eq!(r, EffectResult::NotImplemented);
    assert_eq!(
        state.player.current_hp, 0,
        "abstaining listener must not mutate HP"
    );

    // Prevent + heal: Resolved + HP raised to 30.
    let r = h_should_die_late_heal_and_prevent(&mut state);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.player.current_hp, 30,
        "PREVENT listener mutates current_hp mid-call (canonical LizardTail-class behaviour)"
    );

    // Channel registration round-trips for both listener kinds.
    // Both slots are intentionally finalized to abstain handlers
    // so sibling death-check tests (e.g. combat_loop's
    // `check_combat_end_returns_combat_lost_when_player_dead`)
    // see a vote-neutral bus and exercise the standard
    // death-flip path. The registry is a process-global
    // OnceLock/RwLock; cleanup is a write-not-clear pattern
    // (no public clear API exposed by the macro).
    register_should_die_late(
        RelicId::LizardTail,
        h_should_die_late_heal_and_prevent as ShouldDieLateFn,
    );
    assert!(lookup_should_die_late(RelicId::LizardTail).is_some());
    register_should_die_late(
        RelicId::LizardTail,
        h_should_die_late_abstain as ShouldDieLateFn,
    );
    register_should_die_late(
        RelicId::ChosenCheese,
        h_should_die_late_abstain as ShouldDieLateFn,
    );
    assert!(lookup_should_die_late(RelicId::ChosenCheese).is_some());
}

// --- LizardTail — 2026-07-17 soft-drop census fix ----------------

/// LizardTail #1 — trigger: the armed relic revives the dying player
/// at `max(1, floor(MaxHp / 2))` (C# `LizardTail.cs:AfterPreventingDeath`,
/// `Heal(50)` var: `Math.Max(1, MaxHp * 50/100)` healed from the 0-HP
/// death floor) and consumes itself (`WasUsed = true` → `counter = 1`).
#[test]
#[serial_test::serial(global_registry)]
fn lizard_tail_revives_at_half_max_hp_and_consumes() {
    let mut state = fresh_state_with_player(75, 0);
    give_player_relic(&mut state, RelicKind::LizardTail);
    let result = on_should_die_late_lizard_tail(&mut state);
    assert_eq!(result, EffectResult::Resolved, "armed relic votes prevent");
    assert_eq!(
        state.player.current_hp, 37,
        "revives at floor(75 / 2) = 37 (magnitude: HEAL = 50%)"
    );
    let uid = state.player.creature_uid.unwrap();
    let creature = state.creatures.iter().find(|c| c.id == uid.0).unwrap();
    assert_eq!(creature.current_hp, 37, "creature mirror sees the revive");
    assert_eq!(state.relics[0].counter, 1, "one-shot flag consumed");
}

/// LizardTail #2 — one-shot: a consumed relic (`counter != 0`) abstains
/// and leaves HP untouched (C# `ShouldDieLate` returns true when
/// `WasUsed`), so the standard death flip proceeds. Also pins the
/// no-relic abstain.
#[test]
#[serial_test::serial(global_registry)]
fn lizard_tail_spent_or_absent_does_not_prevent_death() {
    // Absent: no LizardTail on the belt.
    let mut state = fresh_state_with_player(80, 0);
    assert_eq!(
        on_should_die_late_lizard_tail(&mut state),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.current_hp, 0, "absent relic leaves HP at 0");

    // Spent: counter already 1 (used earlier in the run — C# `WasUsed`
    // is a run-persistent `[SavedProperty]`, mirrored via the
    // enter/exit_combat counter bridge).
    give_player_relic(&mut state, RelicKind::LizardTail);
    state.relics[0].counter = 1;
    assert_eq!(
        on_should_die_late_lizard_tail(&mut state),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.current_hp, 0, "spent relic leaves HP at 0");
    assert_eq!(state.relics[0].counter, 1, "spent flag untouched");
}

/// LizardTail #3 — edge: the revive clamps to at least 1 HP (C#
/// `Math.Max(1m, …)`) and never exceeds MaxHp (MaxHp = 1 → revive 1).
/// Also exercises the full registered dispatch path (`ensure_installed`
/// → `dispatch_should_die_late`).
#[test]
#[serial_test::serial(global_registry)]
fn lizard_tail_min_one_hp_revive_via_dispatch() {
    ensure_installed();
    let mut state = fresh_state_with_player(1, 0);
    give_player_relic(&mut state, RelicKind::LizardTail);
    let prevented = dispatch_should_die_late(&mut state);
    assert!(prevented, "registered listener votes prevent");
    assert_eq!(
        state.player.current_hp, 1,
        "max(1, floor(1 / 2)) = 1, capped at MaxHp"
    );
    assert_eq!(state.relics[0].counter, 1, "consumed through dispatch too");
}

