/// the (PotionKind, Option<u8> target) tuple to each listener
/// unchanged. The roundtrip above discards both args via `_kind` /
/// `_target`; a regression that swapped them or dropped one would
/// pass roundtrip but break real listeners (e.g. ToyOrnithopter
/// keys on potion kind; FairyInABottle keys on a target slot).
fn h_after_potion_used_capture(
    _s: &mut CombatState,
    kind: crate::potions::PotionKind,
    target: Option<u8>,
) -> EffectResult {
    LAST_POTION_KIND.store(kind as u32 as usize, Ordering::SeqCst);
    LAST_POTION_TARGET.store(target.map_or(usize::MAX, |t| t as usize), Ordering::SeqCst);
    EffectResult::Resolved
}
static LAST_POTION_KIND: AtomicUsize = AtomicUsize::new(usize::MAX);
static LAST_POTION_TARGET: AtomicUsize = AtomicUsize::new(0);

#[test]
#[serial_test::serial(global_registry)]
fn after_potion_used_dispatch_propagates_kind_and_target() {
    register_after_potion_used(
        RelicId::DeprecatedRelic,
        h_after_potion_used_capture as AfterPotionUsedFn,
    );
    let mut state = CombatState::default();

    // FirePotion + target=Some(3).
    LAST_POTION_KIND.store(usize::MAX, Ordering::SeqCst);
    LAST_POTION_TARGET.store(0, Ordering::SeqCst);
    let _ = dispatch_after_potion_used(&mut state, crate::potions::PotionKind::FirePotion, Some(3));
    assert_eq!(
        LAST_POTION_KIND.load(Ordering::SeqCst),
        crate::potions::PotionKind::FirePotion as u32 as usize,
        "listener must observe the dispatched PotionKind"
    );
    assert_eq!(
        LAST_POTION_TARGET.load(Ordering::SeqCst),
        3,
        "listener must observe Some(3) target"
    );

    // BlockPotion + target=None — both args change, listener observes both.
    let _ = dispatch_after_potion_used(&mut state, crate::potions::PotionKind::BlockPotion, None);
    assert_eq!(
        LAST_POTION_KIND.load(Ordering::SeqCst),
        crate::potions::PotionKind::BlockPotion as u32 as usize
    );
    assert_eq!(
        LAST_POTION_TARGET.load(Ordering::SeqCst),
        usize::MAX,
        "None target encodes as the usize::MAX sentinel"
    );
}

