/// HornCleat: round-2 PLAYER block-clear → +14 unpowered block.
/// Mirrors Python `relics/uncommon.py::HornCleat.after_block_cleared`.
/// Pin (bead `sts2-rs-6ict`):
///   * round 1 / round 3 with relic owned → NotImplemented, no block
///   * round 2 ENEMY side with relic owned → NotImplemented, no block
///   * round 2 PLAYER side without relic → NotImplemented, no block
///   * round 2 PLAYER side with relic → Resolved, +14 block
#[test]
fn horn_cleat_round_2_player_block_clear_gains_14_block() {
    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    state.creatures.push(crate::Creature {
        id: player_uid.0,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: None,
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId(""),
        ai: None,
    });
    state.player.creature_uid = Some(player_uid);
    let ctx = crate::hooks::BlockClearedCtx::default();

    // Round 1 + owned → no fire.
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::HornCleat,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    state.side = Side::Player;
    state.round = 1;
    assert_eq!(
        on_after_block_cleared_horn_cleat(&mut state, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.block, 0, "no block at round 1");

    // Round 2 + Enemy side → no fire.
    state.side = Side::Enemy;
    state.round = 2;
    assert_eq!(
        on_after_block_cleared_horn_cleat(&mut state, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.block, 0, "no block on enemy-side fire");

    // Round 2 + Player + owned → fires, +14 block.
    state.side = Side::Player;
    state.round = 2;
    assert_eq!(
        on_after_block_cleared_horn_cleat(&mut state, &ctx),
        EffectResult::Resolved
    );
    assert_eq!(state.player.block, HORN_CLEAT_BLOCK, "round-2 player gain");

    // Round 3 + Player + owned → no fire (the gain is one-shot at r2).
    state.round = 3;
    state.player.block = 0;
    assert_eq!(
        on_after_block_cleared_horn_cleat(&mut state, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.block, 0, "no block at round 3");

    // Strip the relic; round 2 player → no fire.
    state
        .relics
        .retain(|r| r.kind != crate::RelicKind::HornCleat);
    state.round = 2;
    assert_eq!(
        on_after_block_cleared_horn_cleat(&mut state, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(state.player.block, 0, "no block without ownership");
}

// --- should_clear_block (relic-side, bead `sts2-rs-1h8q` ch.3) -----

fn h_should_clear_block_permit(_s: &CombatState, _ctx: &crate::hooks::BlockClearedCtx) -> bool {
    C_SHOULD_CLEAR_BLOCK.fetch_add(1, Ordering::SeqCst);
    true
}

fn h_should_clear_block_suppress(_s: &CombatState, _ctx: &crate::hooks::BlockClearedCtx) -> bool {
    C_SHOULD_CLEAR_BLOCK.fetch_add(1, Ordering::SeqCst);
    false
}

#[test]
fn should_clear_block_registry_empty_returns_no_listeners() {
    assert!(lookup_should_clear_block(RelicId::Kunai).is_none());
}

#[test]
#[serial_test::serial(global_registry)]
fn should_clear_block_register_and_dispatch_roundtrip() {
    // Two listeners exercise the any-false short-circuit: a
    // suppress listener returns false, so dispatch must return
    // false regardless of the permit listener's vote (which may
    // or may not run depending on BTreeMap iteration order).
    C_SHOULD_CLEAR_BLOCK.store(0, Ordering::SeqCst);
    register_should_clear_block(
        RelicId::SturdyClamp,
        h_should_clear_block_suppress as ShouldClearBlockFn,
    );
    register_should_clear_block(
        RelicId::CaptainsWheel,
        h_should_clear_block_permit as ShouldClearBlockFn,
    );
    let state = CombatState::default();
    let ctx = crate::hooks::BlockClearedCtx::default();
    let result = dispatch_should_clear_block(&state, &ctx);
    assert!(!result, "any-false short-circuit");
    // At least one listener must have fired; short-circuit may
    // skip the second, so `>= 1` is the correct bound.
    assert!(C_SHOULD_CLEAR_BLOCK.load(Ordering::SeqCst) >= 1);
}

