fn modify_damage_multiplicative_registry_empty_returns_no_listeners() {
    // Probe a relic that no test registers on this channel. The
    // roundtrip test below registers PaperPhrog + VitruvianMinion,
    // so neither is a safe empty probe.
    assert!(lookup_modify_damage_multiplicative(RelicId::OddlySmoothStone).is_none());
}

static RE_REGISTER_HALF_CALLS: AtomicUsize = AtomicUsize::new(0);
static RE_REGISTER_DOUBLE_CALLS: AtomicUsize = AtomicUsize::new(0);
#[allow(clippy::trivially_copy_pass_by_ref)]
fn h_re_register_half(
    state: &CombatState,
    _ctx: &crate::hooks::DamageCtx,
) -> crate::hooks::DamageMul {
    RE_REGISTER_HALF_CALLS.fetch_add(1, Ordering::SeqCst);
    if !player_owns_relic(state, crate::RelicKind::AmethystAubergine) {
        return crate::hooks::DamageMul::ONE;
    }
    crate::hooks::DamageMul::new(1, 2)
}
#[allow(clippy::trivially_copy_pass_by_ref)]
fn h_re_register_double(
    state: &CombatState,
    _ctx: &crate::hooks::DamageCtx,
) -> crate::hooks::DamageMul {
    RE_REGISTER_DOUBLE_CALLS.fetch_add(1, Ordering::SeqCst);
    if !player_owns_relic(state, crate::RelicKind::AmethystAubergine) {
        return crate::hooks::DamageMul::ONE;
    }
    crate::hooks::DamageMul::new(2, 1)
}

/// Bead `sts2-rs-nw5tt`: `register_modify_damage_multiplicative`
/// must REPLACE a prior handler when called twice with the same
/// RelicId — the relic_hook_channel! macro (relic_effects.rs:4855)
/// uses BTreeMap::insert. If that registry were ever swapped for
/// a Vec, listeners would double-fire silently on re-init.
///
/// Verify: register half on RelicId X, then re-register double on
/// X. Dispatch once. Double's counter increments by 1; half's
/// counter stays at its baseline (replaced, never reached).
#[test]
#[serial_test::serial(global_registry)]
fn register_modify_damage_multiplicative_replaces_on_same_relic_id() {
    let probe = RelicId::AmethystAubergine;
    register_modify_damage_multiplicative(
        probe,
        h_re_register_half as ModifyDamageMultiplicativeFn,
    );
    register_modify_damage_multiplicative(
        probe,
        h_re_register_double as ModifyDamageMultiplicativeFn,
    );
    // Lookup must resolve to the *most-recent* registration.
    let resolved =
        lookup_modify_damage_multiplicative(probe).expect("post-register lookup is Some");
    let half_baseline = RE_REGISTER_HALF_CALLS.load(Ordering::SeqCst);
    let double_baseline = RE_REGISTER_DOUBLE_CALLS.load(Ordering::SeqCst);

    // Direct fn-pointer call (avoids the registry walk picking up
    // other tests' listeners). The resolved handler must be double.
    let _ = resolved(&CombatState::default(), &crate::hooks::DamageCtx::default());

    assert_eq!(
        RE_REGISTER_HALF_CALLS.load(Ordering::SeqCst),
        half_baseline,
        "half handler must have been replaced — its counter must stay flat"
    );
    assert_eq!(
        RE_REGISTER_DOUBLE_CALLS.load(Ordering::SeqCst),
        double_baseline + 1,
        "double handler is the survivor — its counter must increment by 1"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn modify_damage_multiplicative_register_and_dispatch_roundtrip() {
    register_modify_damage_multiplicative(
        RelicId::PaperPhrog,
        h_modify_damage_multiplicative_half as ModifyDamageMultiplicativeFn,
    );
    register_modify_damage_multiplicative(
        RelicId::VitruvianMinion,
        h_modify_damage_multiplicative_double as ModifyDamageMultiplicativeFn,
    );
    assert!(lookup_modify_damage_multiplicative(RelicId::PaperPhrog).is_some());
    assert!(lookup_modify_damage_multiplicative(RelicId::VitruvianMinion).is_some());
    let state = CombatState::default();
    let ctx = crate::hooks::DamageCtx::default();
    let mul = dispatch_modify_damage_multiplicative(&state, &ctx);
    // 1/2 * 2/1 = 1; with other registered handlers possibly
    // composing in, assert the result lands in [0, 100] for a
    // base of 100 — our two contributions reduce to identity,
    // and there is no >1 relic-side damage-mul handler today.
    let applied = mul.apply(100);
    assert!(
        (0..=100).contains(&applied),
        "expected composed multiplier to land in [0, 100], got {applied}"
    );
}

// --- modify_hp_lost (fold transform) ----------------------------

// The `&ModifyHpLostCtx` parameter is dictated by the public
// `ModifyHpLostFn` type alias. The struct is still small enough
// that clippy flags copy-by-ref; the alias signature is the load-
// bearing surface, so suppress the lint at the handler.
#[allow(clippy::trivially_copy_pass_by_ref)]
fn h_modify_hp_lost_floor_to_one(s: &CombatState, _ctx: &ModifyHpLostCtx, current: i32) -> i32 {
    // `TheBoot` semantics: floor low non-zero damage to 1 (here
    // simplified to always floor to 1 if current > 0). Gate on
    // ownership so sibling tests don't see this fold leak into
    // their damage pipelines via the shared registry.
    if player_owns_relic(s, crate::RelicKind::TheBoot) && current > 0 && current < 5 {
        1
    } else {
        current
    }
}

#[test]
fn modify_hp_lost_registry_empty_returns_no_listeners() {
    // TheBoot is registered by the roundtrip test; probe a
    // distinct relic so this test is order-independent. After
    // bead `sts2-rs-2n11` wired TungstenRod, swap to Pocketwatch
    // (also rare; still unwired on this channel).
    assert!(lookup_modify_hp_lost(RelicId::Pocketwatch).is_none());
}

#[test]
#[serial_test::serial(global_registry)]
fn modify_hp_lost_register_and_dispatch_roundtrip() {
    register_modify_hp_lost(
        RelicId::TheBoot,
        h_modify_hp_lost_floor_to_one as ModifyHpLostFn,
    );
    let state = CombatState::default();
    let ctx = ModifyHpLostCtx {
        target: fake_target(),
        dealer: None,
        props: crate::hooks::ValueProps::NONE,
    };
    let folded = dispatch_modify_hp_lost(&state, &ctx, 3);
    // Either TheBoot floored it to 1, or some other registered
    // handler transformed it further. Assert it's <= the input,
    // confirming the fold actually visited at least one handler.
    assert!(
        folded <= 3,
        "expected fold to apply at least one transform, got {folded}"
    );
    // Bypassing transform: large value should remain large for
    // TheBoot's branch.
    let big = dispatch_modify_hp_lost(&state, &ctx, 100);
    assert!(big >= 1, "fold should produce a non-negative i32");
}

