/// `re_entry_guard_stable`: the bus carries an `AddSource` payload
/// that lets `BingBong`-style listeners self-filter on
/// `BingBongDuplicate` to break recursion. The bus does NOT
/// enforce re-entry on the [`CombatState`] body — the guard lives
/// on the future `BingBong` relic body in the umbrella retrofit
/// `sts2-rs-01o`. This test pins the convention: an
/// `add_to_master_deck(.., Reward)` followed by
/// `duplicate_last_added_card()` produces exactly 2 dispatches,
/// the second carrying `AddSource::BingBongDuplicate`, with the
/// deck growing by exactly 2 (no implicit recursion).
///
/// TODO `sts2-rs-01o`: replace with a real `BingBong`
/// duplicate-then-skip integration test once the relic body lands.
#[test]
#[serial_test::serial(global_registry)]
fn re_entry_guard_stable() {
    register_on_card_added_to_deck(
        RelicId::CrackedCore, // arbitrary slot id; reused only here
        sentinel_on_card_added as OnCardAddedToDeckFn,
    );
    SENTINEL_OBSERVED_DUP.store(false, Ordering::SeqCst);
    SENTINEL_OBSERVED_REWARD.store(false, Ordering::SeqCst);

    let mut state = CombatState::default();
    state.add_to_master_deck(crate::cards::CardId::StrikeIronclad, AddSource::Reward);
    let did = state.duplicate_last_added_card();
    assert!(did);

    assert!(
        SENTINEL_OBSERVED_REWARD.load(Ordering::SeqCst),
        "first dispatch carried AddSource::Reward"
    );
    assert!(
        SENTINEL_OBSERVED_DUP.load(Ordering::SeqCst),
        "second dispatch carried AddSource::BingBongDuplicate"
    );
    assert_eq!(state.master_deck.len(), 2);
}

static SENTINEL_OBSERVED_DUP: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);
static SENTINEL_OBSERVED_REWARD: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

fn sentinel_on_card_added(_s: &mut CombatState, ctx: &CardAddedCtx) -> EffectResult {
    match ctx.source {
        AddSource::Reward => SENTINEL_OBSERVED_REWARD.store(true, Ordering::SeqCst),
        AddSource::BingBongDuplicate => SENTINEL_OBSERVED_DUP.store(true, Ordering::SeqCst),
        _ => {}
    }
    EffectResult::Resolved
}

