// -----------------------------------------------------------------
// Combat surfaces — bead `sts2-rs-jlc` (n3w-b)
// -----------------------------------------------------------------
//
// Three new surfaces:
//   * `creature_gain_max_hp` fires the new
//     `after_max_hp_gained` channel (in addition to the
//     pre-existing `after_max_hp_changed`).
//   * `duplicate_last_added_card` fires `on_card_added_to_deck`
//     with `AddSource::BingBongDuplicate`.
//   * `draw_into_hand` / `shuffle_draw_pile` fire `after_shuffle`.

static C_MAX_HP_GAINED: AtomicUsize = AtomicUsize::new(0);
static LAST_GAIN_DELTA_BIASED: AtomicUsize = AtomicUsize::new(0);
static C_AFTER_SHUFFLE: AtomicUsize = AtomicUsize::new(0);
static LAST_SHUFFLE_FROM_RESHUFFLE: AtomicUsize = AtomicUsize::new(0);
static C_DUPLICATE_LAST_ADDED: AtomicUsize = AtomicUsize::new(0);
static LAST_DUPLICATE_SOURCE: AtomicUsize = AtomicUsize::new(0);

fn h_after_max_hp_gained(_s: &mut CombatState, ctx: &MaxHpChangeCtx) -> EffectResult {
    C_MAX_HP_GAINED.fetch_add(1, Ordering::SeqCst);
    LAST_GAIN_DELTA_BIASED.store((ctx.delta + (1 << 30)) as usize, Ordering::SeqCst);
    EffectResult::Resolved
}

fn h_after_shuffle_jlc(_s: &mut CombatState, ctx: &ShuffleCtx) -> EffectResult {
    C_AFTER_SHUFFLE.fetch_add(1, Ordering::SeqCst);
    LAST_SHUFFLE_FROM_RESHUFFLE.store(usize::from(ctx.from_reshuffle), Ordering::SeqCst);
    EffectResult::Resolved
}

fn h_duplicate_listener(_s: &mut CombatState, ctx: &CardAddedCtx) -> EffectResult {
    C_DUPLICATE_LAST_ADDED.fetch_add(1, Ordering::SeqCst);
    // Bias: encode `AddSource` discriminant as a small unsigned tag.
    let tag: usize = match ctx.source {
        AddSource::Reward => 1,
        AddSource::EventGain => 2,
        AddSource::RelicGain => 3,
        AddSource::BingBongDuplicate => 4,
        AddSource::ShopPurchase => 5,
        AddSource::Other => 6,
    };
    LAST_DUPLICATE_SOURCE.store(tag, Ordering::SeqCst);
    EffectResult::Resolved
}

/// `Creature::gain_max_hp` (via [`CombatState::creature_gain_max_hp`])
/// fires the new `after_max_hp_gained` channel with the positive
/// delta. Bead `sts2-rs-jlc` (n3w-b).
#[test]
#[serial_test::serial(global_registry)]
fn jlc_gain_max_hp_fires_after_max_hp_gained() {
    C_MAX_HP_GAINED.store(0, Ordering::SeqCst);
    register_after_max_hp_gained(
        RelicId::Strawberry,
        h_after_max_hp_gained as AfterMaxHpGainedFn,
    );

    let mut state = CombatState::default();
    state.creatures.push(make_cultist());
    let uid = CreatureUid::new(1).unwrap();

    let before = C_MAX_HP_GAINED.load(Ordering::SeqCst);
    let delta = state.creature_gain_max_hp(uid, 7);
    let after = C_MAX_HP_GAINED.load(Ordering::SeqCst);

    assert_eq!(delta, 7);
    assert!(
        after > before,
        "after_max_hp_gained must fire on positive delta"
    );
    let recorded = LAST_GAIN_DELTA_BIASED.load(Ordering::SeqCst) as i32 - (1 << 30);
    assert_eq!(recorded, 7);

    // Zero / negative gain is a no-op — channel must NOT fire.
    let count_before_noop = C_MAX_HP_GAINED.load(Ordering::SeqCst);
    let _ = state.creature_gain_max_hp(uid, 0);
    let _ = state.creature_gain_max_hp(uid, -3);
    assert_eq!(
        C_MAX_HP_GAINED.load(Ordering::SeqCst),
        count_before_noop,
        "zero / negative gain must not broadcast after_max_hp_gained"
    );

    // Lose path must NOT fire the gain-only channel.
    let count_before_loss = C_MAX_HP_GAINED.load(Ordering::SeqCst);
    let _ = state.creature_lose_max_hp(uid, 2);
    assert_eq!(
        C_MAX_HP_GAINED.load(Ordering::SeqCst),
        count_before_loss,
        "lose_max_hp must not broadcast after_max_hp_gained"
    );
}

/// `CombatState::duplicate_last_added_card` re-routes the duplicate
/// through [`CombatState::add_to_master_deck`] with the
/// `BingBongDuplicate` source, firing `on_card_added_to_deck` once
/// for the duplicate. Bead `sts2-rs-jlc` (n3w-b).
#[test]
#[serial_test::serial(global_registry)]
fn jlc_duplicate_last_added_fires_on_card_added_to_deck() {
    C_DUPLICATE_LAST_ADDED.store(0, Ordering::SeqCst);
    LAST_DUPLICATE_SOURCE.store(0, Ordering::SeqCst);
    register_on_card_added_to_deck(
        RelicId::BingBong,
        h_duplicate_listener as OnCardAddedToDeckFn,
    );

    let mut state = CombatState::default();
    // Empty deck: duplicate must return false and NOT fire the bus.
    let before_empty = C_DUPLICATE_LAST_ADDED.load(Ordering::SeqCst);
    assert!(!state.duplicate_last_added_card());
    assert_eq!(
        C_DUPLICATE_LAST_ADDED.load(Ordering::SeqCst),
        before_empty,
        "empty deck duplicate must not fire the bus"
    );

    // Seed the deck via add_to_master_deck (fires once, source=Reward).
    state.add_to_master_deck(crate::cards::CardId::StrikeIronclad, AddSource::Reward);
    let after_seed = C_DUPLICATE_LAST_ADDED.load(Ordering::SeqCst);
    assert_eq!(LAST_DUPLICATE_SOURCE.load(Ordering::SeqCst), 1);

    // Duplicate the last add: fires once with BingBongDuplicate source.
    assert!(state.duplicate_last_added_card());
    let after_dup = C_DUPLICATE_LAST_ADDED.load(Ordering::SeqCst);
    assert_eq!(
        after_dup,
        after_seed + 1,
        "duplicate must broadcast on_card_added_to_deck once"
    );
    assert_eq!(
        LAST_DUPLICATE_SOURCE.load(Ordering::SeqCst),
        4,
        "duplicate must tag the add as BingBongDuplicate"
    );
    assert_eq!(state.master_deck.len(), 2);
    assert_eq!(state.master_deck[1], crate::cards::CardId::StrikeIronclad);
}

/// `CombatState::shuffle_draw_pile` (explicit shuffle) fires
/// `after_shuffle` once with `from_reshuffle: false`;
/// `CombatState::draw_into_hand` fires once with
/// `from_reshuffle: true` when an auto-reshuffle occurs inside
/// the draw loop. Bead `sts2-rs-jlc` (n3w-b).
#[test]
#[serial_test::serial(global_registry)]
fn jlc_shuffle_surfaces_fire_after_shuffle() {
    C_AFTER_SHUFFLE.store(0, Ordering::SeqCst);
    LAST_SHUFFLE_FROM_RESHUFFLE.store(0, Ordering::SeqCst);
    register_after_shuffle_bus(RelicId::FrozenEgg, h_after_shuffle_jlc as AfterShuffleFn);

    // Explicit shuffle fires once with from_reshuffle == false.
    let mut state = CombatState::default();
    let before_explicit = C_AFTER_SHUFFLE.load(Ordering::SeqCst);
    state.shuffle_draw_pile();
    let after_explicit = C_AFTER_SHUFFLE.load(Ordering::SeqCst);
    assert_eq!(
        after_explicit,
        before_explicit + 1,
        "explicit shuffle_draw_pile must fire after_shuffle once"
    );
    assert_eq!(
        LAST_SHUFFLE_FROM_RESHUFFLE.load(Ordering::SeqCst),
        0,
        "explicit shuffle carries from_reshuffle=false"
    );

    // Auto-reshuffle inside draw: empty draw + non-empty discard +
    // draw N > 0 must trigger the reshuffle and fire after_shuffle
    // once with from_reshuffle == true.
    state.player.draw.clear();
    state.player.discard.clear();
    state.player.hand.clear();
    state.player.discard.push(crate::CardUid::new(1).unwrap());
    state.player.discard.push(crate::CardUid::new(2).unwrap());
    state.player.discard.push(crate::CardUid::new(3).unwrap());
    // Keep combat LIVE so `draw_into_hand`'s combat-is-ending reshuffle gate
    // (skip-reshuffle once the last enemy is down / player dead, mirroring C#
    // `CardPileCmd.Draw` IsOverOrEnding early-return) does NOT fire here — a
    // turn-start/mid-combat draw legitimately reshuffles while combat is live.
    // `CombatState::default()` leaves the player at 0 HP (reads as "combat
    // ending"), which would otherwise cap the draw to the empty draw pile.
    state.player.current_hp = 50;
    state.player.max_hp = 50;
    let enemy = state.spawn_enemy(crate::MonsterKind::Nibbit);
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
        c.current_hp = 30;
    }

    let before_auto = C_AFTER_SHUFFLE.load(Ordering::SeqCst);
    let moved = state.draw_into_hand(2);
    let after_auto = C_AFTER_SHUFFLE.load(Ordering::SeqCst);
    assert_eq!(moved, 2);
    assert_eq!(
        after_auto,
        before_auto + 1,
        "auto-reshuffle must fire after_shuffle once"
    );
    assert_eq!(
        LAST_SHUFFLE_FROM_RESHUFFLE.load(Ordering::SeqCst),
        1,
        "auto-reshuffle carries from_reshuffle=true"
    );

    // draw_into_hand on a non-empty draw pile must NOT shuffle.
    let count_before = C_AFTER_SHUFFLE.load(Ordering::SeqCst);
    let _ = state.draw_into_hand(1);
    assert_eq!(
        C_AFTER_SHUFFLE.load(Ordering::SeqCst),
        count_before,
        "draw_into_hand with non-empty draw pile must not shuffle"
    );
}

/// Pin: the old placeholder `RoomKind` shim is gone — the
