// -----------------------------------------------------------------
// Shop-price modifier channel — bead `sts2-rs-bms`.
// -----------------------------------------------------------------

fn h_shop_price_courier(_s: &CombatState, _ctx: &ShopPriceCtx, current: i32) -> i32 {
    // Courier-style 20% discount.
    ((current as f32) * 0.80).round() as i32
}

/// `dispatch_modify_shop_price` folds every listener's contribution
/// across the running price and clamps the final value to `>= 0`
/// (mirrors Python `apply_merchant_price_modifiers`). With one
/// 20%-discount listener registered, a base price of 100 must fold
/// to 80.
#[test]
#[serial_test::serial(global_registry)]
fn shop_price_fold_applies_courier_discount() {
    // Channel-level fold test. Registers an ungated test shim on a
    // RelicId that has no production shop-price handler so the
    // production `TheCourier` listener (Issue #50) doesn't
    // intermix gating into the fold.
    register_modify_shop_price(
        RelicId::FresnelLens,
        h_shop_price_courier as ModifyShopPriceFn,
    );
    let state = CombatState::default();
    let ctx = ShopPriceCtx {
        item_kind: ShopItemKind::Card,
    };
    let folded = dispatch_modify_shop_price(&state, &ctx, 100);
    assert_eq!(folded, 80, "20% discount of 100 should fold to 80");
    assert!(lookup_modify_shop_price(RelicId::FresnelLens).is_some());

    // Clamp: a "free everything" listener that pushes well below
    // zero must still clamp the final result at 0.
    fn h_negative(_s: &CombatState, _c: &ShopPriceCtx, _: i32) -> i32 {
        -999
    }
    register_modify_shop_price(RelicId::Pendulum, h_negative as ModifyShopPriceFn);
    let folded = dispatch_modify_shop_price(&state, &ctx, 100);
    assert_eq!(folded, 0, "negative folds must clamp to 0");
}

/// Bead `sts2-rs-70anj.4`: MembershipCard production listener
/// directly. Tests the function body in isolation rather than going
/// through `dispatch_modify_shop_price` because tests in this module
/// share a process-global hook registry — earlier shop-price tests
/// (FresnelLens shim, Pendulum negative-fold shim) leave listeners
/// installed that would intermix with the dispatcher fold and make
/// the assertion brittle.
#[test]
fn shop_price_membership_card_production_listener() {
    let mut state = CombatState::default();
    let ctx = ShopPriceCtx {
        item_kind: ShopItemKind::Card,
    };

    // Without ownership: passthrough.
    assert_eq!(
        on_modify_shop_price_membership_card(&state, &ctx, 100),
        100,
        "no relic = no discount"
    );

    // With MembershipCard: 50% off, half-up.
    let id = NonZeroU32::new(u32::try_from(state.relics.len() + 1).unwrap()).unwrap();
    state.relics.push(crate::Relic {
        id,
        kind: RelicKind::MembershipCard,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    assert_eq!(on_modify_shop_price_membership_card(&state, &ctx, 100), 50);
    assert_eq!(
        on_modify_shop_price_membership_card(&state, &ctx, 17),
        9,
        "17 * 50 / 100 = 8.5, half-up = 9"
    );
    assert_eq!(on_modify_shop_price_membership_card(&state, &ctx, 0), 0);
}

