fn h_count_pets_two(s: &CombatState) -> i32 {
    // Ownership gates so the polluting listeners don't contribute
    // to sibling tests' `dispatch_count_pets` reads.
    if !player_owns_relic(s, crate::RelicKind::Byrdpip) {
        return 0;
    }
    2
}
fn h_count_pets_one(s: &CombatState) -> i32 {
    if !player_owns_relic(s, crate::RelicKind::PaelsLegion) {
        return 0;
    }
    1
}

/// `BoundPhylactery`'s production `count_pets` listener returns 0
/// when the player doesn't own the relic, and 1 when an alive Osty
/// is present in `state.creatures`. Bead `sts2-rs-6b0v`. Tests in
/// this module share a process-global hook registry, so we measure
/// the BoundPhylactery delta against a baseline rather than an
/// absolute total.
#[test]
#[serial_test::serial(global_registry)]
fn count_pets_bound_phylactery_production_listener() {
    ensure_installed();
    let mut state = CombatState::default();
    state.player.max_hp = 80;
    state.player.current_hp = 80;
    state.init_player_creature();

    // Baseline: BoundPhylactery owner-gate fails, contributes 0.
    let baseline = dispatch_count_pets(&state);

    // Give the player a BoundPhylactery. Without an Osty in the
    // creature arena, BoundPhylactery's listener still returns 0.
    let id = NonZeroU32::new(u32::try_from(state.relics.len() + 100).unwrap()).unwrap();
    state.relics.push(crate::Relic {
        id,
        kind: RelicKind::BoundPhylactery,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    assert_eq!(dispatch_count_pets(&state), baseline);

    // Summon one Osty: BoundPhylactery contributes +1.
    let osty_id = NonZeroU32::new(u32::try_from(state.creatures.len() + 1).unwrap()).unwrap();
    state.creatures.push(crate::Creature {
        id: osty_id,
        current_hp: 1,
        max_hp: 1,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(crate::MonsterKind::Osty),
        monster_id: crate::MonsterId("Osty"),
        intent: None,
        intent_history: crate::IntentHistory::default(),
        ai: None,
    });
    state.player.pet_uid = Some(crate::CreatureUid(osty_id));
    assert_eq!(dispatch_count_pets(&state), baseline + 1);

    // Dead Osty (hp=0) is not counted — back to baseline.
    state.creatures.last_mut().unwrap().current_hp = 0;
    assert_eq!(dispatch_count_pets(&state), baseline);
}

/// `dispatch_count_pets` sums every listener's contribution. With
/// no listeners registered the dispatcher returns 0; with two
/// listeners contributing 2 and 1 the sum is 3.
#[test]
#[serial_test::serial(global_registry)]
fn count_pets_sums_listeners() {
    // Fresh channel — using two distinct relic ids that no other
    // test in this module registers on the count-pets channel.
    assert!(lookup_count_pets(RelicId::Byrdpip).is_none());
    assert!(lookup_count_pets(RelicId::PaelsLegion).is_none());

    // Empty registry must yield 0.
    let mut state = CombatState::default();
    assert_eq!(dispatch_count_pets(&state), 0);

    register_count_pets(RelicId::Byrdpip, h_count_pets_two as CountPetsFn);
    register_count_pets(RelicId::PaelsLegion, h_count_pets_one as CountPetsFn);

    // Give the player both probe relics so the ownership-gated
    // probe handlers contribute their counts.
    give_player_relic(&mut state, RelicKind::Byrdpip);
    give_player_relic(&mut state, RelicKind::PaelsLegion);

    let total = dispatch_count_pets(&state);
    assert_eq!(total, 3, "expected sum of 2 + 1 across two listeners");
}

