use crate::RelicKind;

fn fresh_state_with_player(max_hp: i32, current_hp: i32) -> CombatState {
    let mut state = CombatState::default();
    state.player.max_hp = max_hp;
    state.player.current_hp = current_hp;
    state.init_player_creature();
    state.round = 1;
    state
}

fn give_player_relic(state: &mut CombatState, kind: RelicKind) {
    let id = NonZeroU32::new(u32::try_from(state.relics.len() + 100).unwrap()).unwrap();
    state.relics.push(crate::Relic {
        id,
        kind,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
}

