/// `BigMushroom.modify_hand_draw` behavioural pin (bead
/// `sts2-rs-ofhd`): round-1 only `draw - 2`, floored at 0;
/// round-2+ unchanged. Mirrors Python
/// `shop_event.py::BigMushroom` (DRAW_PENALTY=2). Companion to
/// the after-obtained max-HP leg (`sts2-rs-46ms`).
#[test]
#[serial_test::serial(global_registry)]
fn big_mushroom_modify_hand_draw_round_1_only() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    let baseline_r1 = dispatch_modify_hand_draw(&state, 5);
    give_player_relic(&mut state, RelicKind::BigMushroom);
    let with_r1 = dispatch_modify_hand_draw(&state, 5);
    assert_eq!(
        baseline_r1 - with_r1,
        BIG_MUSHROOM_DRAW_PENALTY,
        "BigMushroom must subtract DRAW_PENALTY=2 on round 1"
    );
    // Floor at 0: base_draw=1 -> 0, not -1.
    assert_eq!(
        on_modify_hand_draw_big_mushroom(&state, 1),
        0,
        "BigMushroom must floor the penalty at 0 (no negative draws)"
    );
    // Round 2+: penalty is gone (listener gate `round_no() != 1`).
    state.round = 2;
    assert_eq!(
        on_modify_hand_draw_big_mushroom(&state, 5),
        5,
        "BigMushroom must not affect hand draw past round 1"
    );
}

/// `BigMushroom` ownership gate: unowned relic must never subtract
/// from hand draw. The dispatch bus iterates every registered
/// listener; the listener's own gate is what makes this a no-op.
#[test]
#[serial_test::serial(global_registry)]
fn big_mushroom_modify_hand_draw_is_noop_without_ownership() {
    ensure_installed();
    let state = fresh_state_with_player(70, 70);
    assert_eq!(state.round, 1);
    assert_eq!(
        on_modify_hand_draw_big_mushroom(&state, 5),
        5,
        "BigMushroom listener must not subtract when unowned"
    );
}

/// `PaelsBlood.modify_hand_draw` behavioural pin (bead
/// `sts2-rs-nxqt`): +1 card every turn, unconditional on round
/// number. Diverges from BagOfPreparation's round-1 gate by
/// design (`shop_event.py::PaelsBlood`).
#[test]
#[serial_test::serial(global_registry)]
fn paels_blood_adds_one_to_hand_draw_every_round() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    let baseline_r1 = dispatch_modify_hand_draw(&state, 5);
    give_player_relic(&mut state, RelicKind::PaelsBlood);
    let with_relic_r1 = dispatch_modify_hand_draw(&state, 5);
    assert_eq!(
        with_relic_r1 - baseline_r1,
        1,
        "PaelsBlood +EXTRA_DRAW=1 on round 1"
    );
    state.round = 5;
    let baseline_r5 = dispatch_modify_hand_draw(&state, 5);
    // Re-equip not needed; remove + add inverse measurement.
    // baseline_r5 already includes PaelsBlood since it persists.
    // Instead, measure: dropping PaelsBlood should reduce draw by 1.
    let _ = state.relics.pop();
    let without_relic_r5 = dispatch_modify_hand_draw(&state, 5);
    assert_eq!(
        baseline_r5 - without_relic_r5,
        1,
        "PaelsBlood bonus persists past round 1"
    );
}

