// Bead `sts2-rs-15y2` — Vambrace +1 Strength at combat start.
// Body matches the 15y2 description (mirrors Vajra); pin-faithful
// double-block rewrite tracked in `sts2-rs-6z05`.
// -----------------------------------------------------------------

fn player_strength(state: &CombatState) -> i32 {
    let player_creature = state
        .player
        .creature_uid
        .and_then(|uid| state.creatures.iter().find(|c| c.id == uid.0));
    let Some(creature) = player_creature else {
        return 0;
    };
    creature
        .powers
        .iter()
        .filter_map(|uid| {
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0 && p.kind == crate::PowerKind::Strength)
                .map(|p| p.amount)
        })
        .sum()
}

