/// Vambrace doubles the FIRST card-granted block each combat, then never
/// again (one-shot latch). Bead `sts2-rs-6z05`.
#[test]
#[serial_test::serial(global_registry)]
fn vambrace_doubles_first_card_block_then_latches() {
    use crate::card_effects::gain_block_player;
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::Vambrace);
    let _ = dispatch_before_combat_start(&mut state); // arm (counter = 0)

    // Card 1 "in play" so its block grant is card-sourced.
    let card1 = crate::CardUid(NonZeroU32::new(1).unwrap());
    state.player.play.push(card1);

    // First card block: 5 doubled to 10.
    gain_block_player(&mut state, 5);
    assert_eq!(state.player.block, 10, "first card block doubled");

    // Resolve card 1 → latch used (card_uid matches the window's triggering
    // card, mirroring C# `cardPlay.Card == TriggeringCard`).
    state.player.play.pop();
    let ctx1 = CardEventCtx {
        card_id: crate::cards::CardId::DefendIronclad,
        card_uid: Some(card1),
        target: None,
        card_tags: crate::cards::CardTags::NONE,
        energy_spent: 0,
    };
    let _ = dispatch_after_card_played(&mut state, &ctx1);

    // Card 2 played afterwards: its block is NOT doubled (10 + 5 = 15).
    let card2 = crate::CardUid(NonZeroU32::new(2).unwrap());
    state.player.play.push(card2);
    gain_block_player(&mut state, 5);
    assert_eq!(state.player.block, 15, "subsequent card block not doubled");
}

/// Vambrace's one-shot window is keyed to the SPECIFIC triggering card
/// (C# `TriggeringCard`): a *different* card that gains block while the
/// window is still open — e.g. a block-gaining card still in-flight whose
/// rider plays Fisticuffs (nested) — is NOT doubled. The prior
/// identity-free `counter <= 0` gate over-doubled that second card's block
/// (exact 2× over-grant; parity tail triage 2026-06-08). Bead `sts2-rs-6z05`.
#[test]
#[serial_test::serial(global_registry)]
fn vambrace_does_not_double_different_card_while_window_open() {
    use crate::card_effects::gain_block_player;
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::Vambrace);
    let _ = dispatch_before_combat_start(&mut state); // arm

    // Card A (the rider) is still in-flight: it gains block (doubled, opens
    // the window for A) and has NOT yet fired after_card_played.
    let card_a = crate::CardUid(NonZeroU32::new(1).unwrap());
    state.player.play.push(card_a);
    gain_block_player(&mut state, 5);
    assert_eq!(
        state.player.block, 10,
        "rider A's block doubled (window opens for A)"
    );

    // A nests a play of card B (Fisticuffs) — B becomes the play-pile top.
    // A's after_card_played has NOT fired, so the window is still open, but
    // it is keyed to A, not B.
    let card_b = crate::CardUid(NonZeroU32::new(2).unwrap());
    state.player.play.push(card_b);
    gain_block_player(&mut state, 5);
    assert_eq!(
        state.player.block, 15,
        "nested card B's block is NOT doubled while the window is open for A \
         (10 + 5, not 10 + 10)"
    );

    // B resolves (it became the new triggering card on its block gain), then A.
    state.player.play.pop();
    let ctx_b = CardEventCtx {
        card_id: crate::cards::CardId::Fisticuffs,
        card_uid: Some(card_b),
        target: None,
        card_tags: crate::cards::CardTags::NONE,
        energy_spent: 0,
    };
    let _ = dispatch_after_card_played(&mut state, &ctx_b);
    state.player.play.pop();
    let ctx_a = CardEventCtx {
        card_id: crate::cards::CardId::DefendIronclad,
        card_uid: Some(card_a),
        target: None,
        card_tags: crate::cards::CardTags::NONE,
        energy_spent: 0,
    };
    let _ = dispatch_after_card_played(&mut state, &ctx_a);

    // One-shot is now spent: a later card gains undoubled block.
    let card_c = crate::CardUid(NonZeroU32::new(3).unwrap());
    state.player.play.push(card_c);
    gain_block_player(&mut state, 5);
    assert_eq!(
        state.player.block, 20,
        "one-shot spent — later block not doubled"
    );
}

/// Vambrace does not double non-card (system) block.
