#[test]
#[serial_test::serial(global_registry)]
fn petrified_toad_respects_belt_size_not_absolute_max() {
    ensure_installed();
    // C# `TryToProcure` → `AddPotionInternal` only fills an EMPTY belt slot
    // (`MaxPotionCount`, here 3), failing `TooFull` otherwise — the cap is
    // the player's belt size, NOT the absolute `MAX_POTIONS = 5`. Bead
    // `sts2-rs-v5ku`: the prior `>= MAX_POTIONS` guard surfaced a phantom 4th
    // `use_potion` slot when the player started with a full 3-potion belt.

    // A full 3-slot belt → no procure (this is the bug the fix closes:
    // under the old `>= MAX_POTIONS(5)` guard the 4th potion was pushed).
    let mut full = fresh_state_with_player(70, 70);
    give_player_relic(&mut full, RelicKind::PetrifiedToad);
    full.player.potion_slots = 3;
    for _ in 0..3 {
        full.player
            .potions
            .push(crate::potions::PotionKind::BlockPotion);
    }
    let _ = dispatch_before_combat_start_late(&mut full);
    assert_eq!(
        full.player.potions.len(),
        3,
        "full 3-slot belt → no PotionShapedRock (cap is belt size, not MAX_POTIONS)"
    );

    // A 3-slot belt with one free slot → procure into it.
    let mut room = fresh_state_with_player(70, 70);
    give_player_relic(&mut room, RelicKind::PetrifiedToad);
    room.player.potion_slots = 3;
    for _ in 0..2 {
        room.player
            .potions
            .push(crate::potions::PotionKind::BlockPotion);
    }
    let _ = dispatch_before_combat_start_late(&mut room);
    assert_eq!(room.player.potions.len(), 3, "free slot → procured");
    assert_eq!(
        room.player.potions[2],
        crate::potions::PotionKind::PotionShapedRock,
        "the procured potion is PotionShapedRock"
    );
}

