#[test]
#[serial_test::serial(global_registry)]
fn big_hat_gates_off_round_and_side_correctly() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::BigHat);
    state.player.character = Some(crate::potions::CharacterId::Necrobinder);
    let hand_before = state.player.hand.len();

    // Round 2 — gated out by round_no != 1.
    state.round = 2;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "BigHat must not fire on round != 1"
    );

    // Round 1 Enemy side — gated out by side check.
    state.round = 1;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Enemy);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "BigHat must not fire on Enemy side"
    );

    // Round 1 Player side, Necrobinder pool (no *_SPECS at this
    // pin) — sampler returns empty, body NotImplemented; no panic,
    // no hand mutation.
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "Necrobinder pool unbuilt → sampler empty → no hand change"
    );
}

