/// Bead `sts2-rs-t7vn` — VexingPuzzlebox gate matrix:
/// * Round 2 PLAYER side → no fire (round_no != 1).
/// * Round 1 ENEMY side → no fire (side != Player).
/// * No character set → no fire (let-Some early-out).
/// * Round 1 PLAYER side, character set, sampler-empty pool
///   (core-only test build / Necrobinder unbuilt) → NotImplemented,
///   no hand mutation.
#[test]
#[serial_test::serial(global_registry)]
fn vexing_puzzlebox_gates_off_round_side_and_character() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::VexingPuzzlebox);
    let hand_before = state.player.hand.len();

    // Round 2 → no fire.
    state.round = 2;
    state.player.character = Some(crate::potions::CharacterId::Necrobinder);
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "VexingPuzzlebox must not fire on round != 1"
    );

    // Round 1 Enemy side → no fire.
    state.round = 1;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Enemy);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "VexingPuzzlebox must not fire on Enemy side"
    );

    // Round 1 Player side, character unset → no fire.
    state.player.character = None;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "no character → no hand mutation"
    );

    // Round 1 Player side, character set, empty pool → NotImplemented,
    // no hand mutation (sampler returns empty in core-only build).
    state.player.character = Some(crate::potions::CharacterId::Necrobinder);
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "empty sampler → no hand mutation"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn red_mask_applies_weak_to_all_alive_enemies_round_one() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::RedMask);
    // Two alive enemies (uids 11 + 12); player's own creature uid is 1.
    for slot in [11_u32, 12_u32] {
        let id = NonZeroU32::new(slot).expect("non-zero");
        state.creatures.push(crate::Creature {
            id,
            current_hp: 30,
            max_hp: 30,
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: Some(crate::MonsterKind::Nibbit),
            intent: None,
            intent_history: crate::IntentHistory::default(),
            monster_id: crate::MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(id));
    }

    let _ = dispatch_before_side_turn_start(&mut state, Side::Player);

    for uid in state.enemy_uids.clone() {
        let creature = state.creatures.iter().find(|c| c.id == uid.0).unwrap();
        let has_weak = creature.powers.iter().copied().any(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0)
                .is_some_and(|p| p.kind == PowerKind::Weak && p.amount >= 1)
        });
        assert!(has_weak, "enemy {uid:?} should carry WEAK after RedMask");
    }
}

