// Bead `sts2-rs-7po6` — LetterOpener three-channel body.
// -----------------------------------------------------------------

fn letter_opener_counter(state: &CombatState) -> i32 {
    state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::LetterOpener)
        .map(|r| r.counter)
        .unwrap()
}

fn push_enemy(state: &mut CombatState, id_raw: u32, hp: i32) -> CreatureUid {
    let id = NonZeroU32::new(id_raw).expect("non-zero");
    state.creatures.push(crate::Creature {
        id,
        current_hp: hp,
        max_hp: hp,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(crate::MonsterKind::Nibbit),
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId("Nibbit"),
        ai: None,
    });
    let uid = CreatureUid(id);
    state.enemy_uids.push(uid);
    uid
}

fn push_card(
    state: &mut CombatState,
    uid_raw: u32,
    card_type: crate::cards::CardType,
) -> crate::CardUid {
    let uid = crate::CardUid::new(uid_raw).expect("non-zero");
    let mut card = crate::cards::Card::pod_defaults();
    card.uid = uid;
    card.card_type = card_type;
    state.cards.push(card);
    uid
}

fn make_card_ctx(uid: crate::CardUid) -> CardEventCtx {
    CardEventCtx {
        card_id: crate::cards::CardId::StrikeIronclad,
        card_uid: Some(uid),
        target: None,
        card_tags: crate::cards::CardTags::NONE,
        energy_spent: 0,
    }
}

#[test]
#[serial_test::serial(global_registry)]
fn rainbow_ring_caps_at_one_activation_per_turn() {
    // C# `RainbowRing.AfterCardPlayed` gates on `ActivationCountThisTurn < 1`:
    // it grants +1 Strength / +1 Dexterity at most ONCE per turn no matter how
    // many attack/skill/power cycles are played. A second full cycle in the
    // same turn must NOT re-grant. Per-turn reset re-arms it.
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::RainbowRing);

    // First full attack→skill→power cycle this turn → one activation.
    for (raw, ty) in [
        (80, crate::cards::CardType::Attack),
        (81, crate::cards::CardType::Skill),
        (82, crate::cards::CardType::Power),
    ] {
        let uid = push_card(&mut state, raw, ty);
        let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    }
    assert_eq!(player_strength(&state), 1, "first cycle grants +1 Strength");

    // Second full cycle in the SAME turn → capped, no further grant.
    for (raw, ty) in [
        (83, crate::cards::CardType::Attack),
        (84, crate::cards::CardType::Skill),
        (85, crate::cards::CardType::Power),
    ] {
        let uid = push_card(&mut state, raw, ty);
        let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    }
    assert_eq!(
        player_strength(&state),
        1,
        "second cycle in the same turn must not re-grant (once-per-turn cap)"
    );

    // New turn re-arms the relic; another full cycle grants again.
    let _ = dispatch_before_side_turn_start(&mut state, Side::Player);
    for (raw, ty) in [
        (86, crate::cards::CardType::Attack),
        (87, crate::cards::CardType::Skill),
        (88, crate::cards::CardType::Power),
    ] {
        let uid = push_card(&mut state, raw, ty);
        let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    }
    assert_eq!(
        player_strength(&state),
        2,
        "next turn re-arms: a fresh cycle grants again"
    );
}

fn set_letter_opener_counter(state: &mut CombatState, value: i32) {
    for r in &mut state.relics {
        if r.kind == RelicKind::LetterOpener {
            r.counter = value;
        }
    }
}

#[test]
#[serial_test::serial(global_registry)]
fn letter_opener_after_side_turn_start_resets_counter() {
    // C# `LetterOpener.AfterSideTurnStart` (LetterOpener.cs:96-109): the
    // reset moved to the AFTER hook (behind the turn-start auto-play
    // cluster) and skips round 1.
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::LetterOpener);
    set_letter_opener_counter(&mut state, 5);
    state.round = 1;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(letter_opener_counter(&state), 5, "round 1: no reset");
    state.round = 2;
    let _ = dispatch_after_side_turn_start(&mut state, Side::Player);
    assert_eq!(letter_opener_counter(&state), 0, "round >1 resets");
}

