// -----------------------------------------------------------------
// Mummified Hand — on playing a Power, free a random hand card for
// THIS TURN (C# `SetToFreeThisTurn`), not a permanent cost mutation.
// Uses sequential uids 1..=3 so `set_card_var`'s uid→index math holds.
// -----------------------------------------------------------------

#[test]
#[serial_test::serial(global_registry)]
fn mummified_hand_frees_one_hand_card_this_turn_without_mutating_base_cost() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MummifiedHand);
    // Two cost-1 Attack candidates in hand (uids 1,2 → cards[0],[1]).
    let a = push_card(&mut state, 1, crate::cards::CardType::Attack);
    let b = push_card(&mut state, 2, crate::cards::CardType::Attack);
    for uid in [a, b] {
        let idx = uid.0.get() as usize - 1;
        state.cards[idx].cost = 1;
        state.player.hand.push(uid);
    }
    // Playing a Power (uid 3) triggers the relic.
    let pow = push_card(&mut state, 3, crate::cards::CardType::Power);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(pow));

    let free = |uid: crate::CardUid| {
        state.cards[uid.0.get() as usize - 1].combat_var(crate::cards::VarKey::FreeThisTurn)
    };
    assert_eq!(
        free(a) + free(b),
        1,
        "exactly one hand card freed this turn"
    );
    // Regression (Regent seed 1005): the freed card's stored base cost must
    // stay 1 — `SetToFreeThisTurn` is a this-turn modifier cleared at turn
    // end, NOT a permanent `card.cost = 0` that survives discard → redraw.
    assert_eq!(state.cards[a.0.get() as usize - 1].cost, 1);
    assert_eq!(state.cards[b.0.get() as usize - 1].cost, 1);
}

#[test]
#[serial_test::serial(global_registry)]
fn mummified_hand_skips_already_free_card() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MummifiedHand);
    // One candidate already free this turn (uid 1), one fresh (uid 2).
    let already_free = push_card(&mut state, 1, crate::cards::CardType::Attack);
    let fresh = push_card(&mut state, 2, crate::cards::CardType::Attack);
    for uid in [already_free, fresh] {
        let idx = uid.0.get() as usize - 1;
        state.cards[idx].cost = 1;
        state.player.hand.push(uid);
    }
    state.cards[already_free.0.get() as usize - 1]
        .set_combat_var(crate::cards::VarKey::FreeThisTurn, 1);
    let pow = push_card(&mut state, 3, crate::cards::CardType::Power);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(pow));
    // C# excludes the already-free card (local cost 0), so only `fresh` can
    // be (re-)freed — the relic never wastes its pick on an already-free card.
    assert_eq!(
        state.cards[fresh.0.get() as usize - 1].combat_var(crate::cards::VarKey::FreeThisTurn),
        1,
        "the only non-free candidate is the one freed"
    );
}

/// C# `CostsEnergyOrStars(includeGlobalModifiers: true)` sees global cost
/// modifiers: under Corruption a skill costs 0, so the first pool holds only
/// the attack. The port used to check only the two free flags, so it could
/// spend the relic on a skill Corruption had already made free.
#[test]
#[serial_test::serial(global_registry)]
fn mummified_hand_skips_a_card_a_global_modifier_already_made_free() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MummifiedHand);
    let corruption = std::num::NonZeroU32::new(1).unwrap();
    state.powers.push(crate::Power {
        id: corruption,
        kind: crate::PowerKind::Corruption,
        amount: 1,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(crate::PowerUid(corruption));
    // Three 1-cost skills (free under Corruption) and one 1-cost attack.
    let mut hand = Vec::new();
    for (uid, card_type) in [
        (1, crate::cards::CardType::Skill),
        (2, crate::cards::CardType::Skill),
        (3, crate::cards::CardType::Skill),
        (4, crate::cards::CardType::Attack),
    ] {
        let card = push_card(&mut state, uid, card_type);
        state.cards[uid as usize - 1].cost = 1;
        state.player.hand.push(card);
        hand.push(card);
    }
    let pow = push_card(&mut state, 5, crate::cards::CardType::Power);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(pow));

    let free = |uid: crate::CardUid| {
        state.cards[uid.0.get() as usize - 1].combat_var(crate::cards::VarKey::FreeThisTurn)
    };
    assert_eq!(
        free(hand[3]),
        1,
        "the attack is the only card that still costs"
    );
    assert_eq!(free(hand[0]) + free(hand[1]) + free(hand[2]), 0);
}

// -----------------------------------------------------------------
// Power Cell — turn-1 start, pull up to POWER_CELL_CARDS (=2) random
// 0-cost cards from the draw pile to hand, off `combat_card_selection`
// via StableShuffle. Uses sequential uids 1..=4.
// -----------------------------------------------------------------

#[test]
#[serial_test::serial(global_registry)]
fn power_cell_pulls_two_zero_cost_cards_from_draw_on_turn_one() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::PowerCell);
    // Draw pile: three 0-cost Attacks (uids 1,2,3) + one cost-1 (uid 4).
    for raw in 1..=4 {
        let uid = push_card(&mut state, raw, crate::cards::CardType::Attack);
        state.cards[uid.0.get() as usize - 1].cost = i8::from(raw == 4);
        state.player.draw.push(uid);
    }
    let _ = dispatch_before_side_turn_start(&mut state, Side::Player);
    // Exactly 2 cards pulled to hand, both 0-cost; the cost-1 card and one
    // leftover 0-cost card stay in draw.
    assert_eq!(state.player.hand.len(), 2, "two cards pulled to hand");
    for &uid in &state.player.hand {
        assert_eq!(
            state.cards[uid.0.get() as usize - 1].cost,
            0,
            "only 0-cost cards are eligible"
        );
    }
    let cost1 = crate::CardUid::new(4).unwrap();
    assert!(
        state.player.draw.contains(&cost1),
        "cost-1 card never pulled"
    );
    assert_eq!(state.player.draw.len(), 2);
}

