// -----------------------------------------------------------------

fn joss_paper_counter(state: &CombatState) -> i32 {
    state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::JossPaper)
        .map(|r| r.counter)
        .unwrap()
}

fn set_joss_paper_counter(state: &mut CombatState, value: i32) {
    for r in &mut state.relics {
        if r.kind == RelicKind::JossPaper {
            r.counter = value;
        }
    }
}

fn joss_paper_state_with_draw_pile(n_cards: u32) -> CombatState {
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::JossPaper);
    for raw in 900..(900 + n_cards) {
        let uid = crate::CardUid::new(raw).expect("non-zero");
        let mut card = crate::cards::Card::pod_defaults();
        card.uid = uid;
        card.card_type = crate::cards::CardType::Skill;
        state.cards.push(card);
        state.player.draw.push(uid);
    }
    state
}

#[test]
#[serial_test::serial(global_registry)]
fn joss_paper_no_draw_on_first_four_exhausts() {
    ensure_installed();
    let mut state = joss_paper_state_with_draw_pile(10);
    let hand_before = state.player.hand.len();
    for raw in 920..924 {
        let uid = push_card(&mut state, raw, crate::cards::CardType::Skill);
        let _ = dispatch_after_card_exhausted(&mut state, &make_card_ctx(uid));
    }
    assert_eq!(joss_paper_counter(&state), 4);
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "first 4 exhausts do not draw"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn joss_paper_fifth_exhaust_draws_one() {
    ensure_installed();
    let mut state = joss_paper_state_with_draw_pile(10);
    let hand_before = state.player.hand.len();
    set_joss_paper_counter(&mut state, 4);
    let uid = push_card(&mut state, 930, crate::cards::CardType::Skill);
    let _ = dispatch_after_card_exhausted(&mut state, &make_card_ctx(uid));
    // C# `DrawIfThresholdMet` (`JossPaper.cs:119-127`): after the threshold
    // draw the counter wraps (`CardsExhausted %= 5`) — it reads 0, not 5.
    assert_eq!(joss_paper_counter(&state), 0);
    assert_eq!(
        state.player.hand.len(),
        hand_before + 1,
        "5th exhaust draws 1"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn joss_paper_counter_persists_across_turns() {
    ensure_installed();
    let mut state = joss_paper_state_with_draw_pile(10);
    set_joss_paper_counter(&mut state, 3);
    let _ = dispatch_before_side_turn_start(&mut state, Side::Player);
    assert_eq!(
        joss_paper_counter(&state),
        3,
        "JossPaper counter is combat-scoped, not per-turn"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn joss_paper_after_combat_end_persists_counter() {
    // C# `CardsExhausted` is a [SavedProperty] (`JossPaper.cs:58`) — it
    // persists across combats; `AfterCombatEnd` (`JossPaper.cs:137-141`)
    // resets the EtherealCount ONLY. The exhaust counter must survive the
    // combat boundary (it is flushed to `rs.relic_counters` by `exit_combat`
    // and re-seeded next fight). Regression for sts2-rs-RP20.
    ensure_installed();
    let mut state = joss_paper_state_with_draw_pile(0);
    set_joss_paper_counter(&mut state, 7);
    state.combat_log.joss_paper_ethereal_count = 2;
    let _ = dispatch_after_combat_end(&mut state);
    assert_eq!(
        joss_paper_counter(&state),
        7,
        "CardsExhausted persists across combat end"
    );
    assert_eq!(
        state.combat_log.joss_paper_ethereal_count, 0,
        "EtherealCount is reset at combat end"
    );
}

