// -----------------------------------------------------------------
// RazorTooth — upgrade every played Attack/Skill for the combat
// (C# v0.107.1 `RazorTooth.cs::AfterCardPlayed`: type must be Attack
// or Skill and `IsUpgradable`; then `CardCmd.Upgrade`).
// -----------------------------------------------------------------

fn razor_card(state: &CombatState, uid: crate::CardUid) -> &crate::cards::Card {
    state
        .cards
        .iter()
        .find(|c| c.uid == uid)
        .expect("card exists")
}

#[test]
#[serial_test::serial(global_registry)]
fn razor_tooth_upgrades_played_attack() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::RazorTooth);
    let uid = push_card(&mut state, 90, crate::cards::CardType::Attack);
    let result = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    assert_eq!(result, EffectResult::Resolved);
    assert!(
        razor_card(&state, uid).upgraded,
        "played Attack must be upgraded"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn razor_tooth_upgrades_played_skill() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::RazorTooth);
    let uid = push_card(&mut state, 91, crate::cards::CardType::Skill);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    assert!(
        razor_card(&state, uid).upgraded,
        "played Skill must be upgraded"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn razor_tooth_ignores_power_and_status() {
    // C# gates on `(uint)(type - 1) <= 1` — only Attack (1) / Skill (2).
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::RazorTooth);
    let power_uid = push_card(&mut state, 92, crate::cards::CardType::Power);
    let status_uid = push_card(&mut state, 93, crate::cards::CardType::Status);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(power_uid));
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(status_uid));
    assert!(
        !razor_card(&state, power_uid).upgraded,
        "Power cards are not upgraded"
    );
    assert!(
        !razor_card(&state, status_uid).upgraded,
        "Status cards are not upgraded"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn razor_tooth_replaying_upgraded_card_is_noop() {
    // C# checks `IsUpgradable` (false once `CurrentUpgradeLevel >=
    // MaxUpgradeLevel`) before `CardCmd.Upgrade`; the Rust port relies
    // on `Card::upgrade` idempotency (returns false when already
    // upgraded) — replaying an upgraded Attack must not stack deltas.
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::RazorTooth);
    let uid = push_card(&mut state, 94, crate::cards::CardType::Attack);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    assert!(razor_card(&state, uid).upgraded);
    let (cost, dmg) = {
        let c = razor_card(&state, uid);
        (c.cost, c.base_damage)
    };
    // Play the same (now-upgraded) card again.
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(uid));
    let c = razor_card(&state, uid);
    assert!(c.upgraded, "still upgraded");
    assert_eq!(c.cost, cost, "second play must not re-apply cost delta");
    assert_eq!(
        c.base_damage, dmg,
        "second play must not re-apply damage delta"
    );
}

