#[test]
#[serial_test::serial(global_registry)]
fn mercury_hourglass_player_turn_deals_three_to_all_enemies() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MercuryHourglass);
    let e1 = push_enemy(&mut state, 400, 30);
    let e2 = push_enemy(&mut state, 401, 30);
    // Bead `sts2-rs-axdgh`: MercuryHourglass is now on the player-only
    // `after_player_turn_start` channel (C# `AfterPlayerTurnStart`), not the
    // side hook — it fires before the side-hook Rampart grant.
    let _ = dispatch_after_player_turn_start(&mut state);
    for uid in [e1, e2] {
        let hp = state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .map(|c| c.current_hp)
            .unwrap();
        assert_eq!(hp, 30 - 3, "MercuryHourglass deals 3 to each enemy");
    }
}

