#[serial_test::serial(global_registry)]
fn self_forming_clay_noop_when_target_is_enemy() {
    ensure_installed();
    let mut state = self_forming_clay_state();
    // Build an Enemy-target ctx so the listener's target-gate fails.
    let enemy_uid = state
        .enemy_uids
        .first()
        .copied()
        .unwrap_or_else(|| crate::CreatureUid(std::num::NonZeroU32::new(u32::MAX).unwrap()));
    let ctx = crate::hooks::DamageCtx {
        target: crate::hooks::CreatureRef::Enemy(enemy_uid),
        ..crate::hooks::DamageCtx::default()
    };
    let _ = dispatch_after_damage_received(&mut state, &ctx, 5);
    assert_eq!(player_self_forming_clay_stacks(&state), 0);
}

