// Integration: the `after_death` bus is wired into the `just_died` chokepoint
// of `apply_damage`, so a *lethal* hit fires GremlinHorn exactly once and a
// *non-lethal* hit does not (bead `sts2-rs-rmrzx`).
#[test]
#[serial_test::serial(global_registry)]
fn gremlin_horn_fires_once_on_lethal_hit_via_apply_damage() {
    ensure_installed();
    let (mut state, uid) = gremlin_horn_state(9);
    let before_energy = state.player.energy;
    let _ = crate::damage::apply_damage(
        &mut state,
        crate::hooks::CreatureRef::Player,
        uid,
        9,
        crate::hooks::ValueProps::NONE,
        None,
    );
    assert!(
        state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .is_some_and(|c| c.current_hp <= 0),
        "enemy should be dead"
    );
    assert_eq!(
        state.player.energy - before_energy,
        GREMLIN_HORN_ENERGY,
        "a lethal hit should grant exactly +1 energy (once)"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn gremlin_horn_noop_on_nonlethal_hit_via_apply_damage() {
    ensure_installed();
    let (mut state, uid) = gremlin_horn_state(15);
    let before_energy = state.player.energy;
    let _ = crate::damage::apply_damage(
        &mut state,
        crate::hooks::CreatureRef::Player,
        uid,
        9,
        crate::hooks::ValueProps::NONE,
        None,
    );
    assert_eq!(
        state.player.energy, before_energy,
        "a non-lethal hit must not trigger GremlinHorn"
    );
}

