fn player_power_amount_for(state: &CombatState, uid: CreatureUid, kind: PowerKind) -> i32 {
    let Some(c) = state.creatures.iter().find(|c| c.id == uid.0) else {
        return 0;
    };
    for puid in &c.powers {
        if let Some(p) = state.powers.get_by_id(puid.0) {
            if p.kind == kind {
                return p.amount;
            }
        }
    }
    0
}

// ── Bead `sts2-rs-47jv` smoke tests ───────────────────────────────
//
// Channel-infra bead — assert the 5 new power-amount channels
// round-trip register → dispatch with the documented fold semantics.
// RuinedHelmet/SneckoSkull/UnsettlingLamp use these in follow-up
// beads (npg1, lcje, 7uo4); the smoke tests here exercise the
// dispatcher mechanics independently of any specific relic body.

/// Empty-bus early-out: each channel returns the unmodified amount
/// (modify) or `NotImplemented` (observer) when no listener is
/// registered. Smoke test for the `is_empty_*` short-circuit path.
///
/// `#[serial(global_registry)]` — races otherwise with any sibling
/// test that registers a power-amount listener without an ownership
/// gate. The empty-bus assertion is order-dependent against the
/// process-global registry; the serial guard keeps it deterministic
/// without forcing the whole suite to `--test-threads=1`.
#[test]
#[serial_test::serial(global_registry)]
fn power_amount_channels_empty_bus_passthrough() {
    let state = CombatState::default();
    let mut state_mut = state.clone();
    let ctx = crate::hooks::PowerAmountCtx::new(
        None,
        crate::hooks::CreatureRef::Player,
        PowerKind::Strength,
        5,
    );
    assert_eq!(dispatch_modify_power_amount_given(&state, &ctx), 5);
    assert_eq!(dispatch_modify_power_amount_received(&state, &ctx), 5);
    assert_eq!(
        dispatch_before_power_amount_changed(&mut state_mut, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(
        dispatch_after_modifying_power_amount_given(&mut state_mut, &ctx),
        EffectResult::NotImplemented
    );
    assert_eq!(
        dispatch_after_modifying_power_amount_received(&mut state_mut, &ctx),
        EffectResult::NotImplemented
    );
}

/// `modify_power_amount_given` listener receives `ctx.amount` and
/// returns a modified amount; the dispatcher threads it through.
/// Verifies the chain-style fold matches SneckoSkull's
/// `+1 Poison given` shape (`amount + 1`).
#[test]
#[serial_test::serial(global_registry)]
fn modify_power_amount_given_listener_modifies_amount() {
    fn h_plus_one(_state: &CombatState, ctx: &crate::hooks::PowerAmountCtx) -> i32 {
        ctx.amount + 1
    }
    register_modify_power_amount_given(
        RelicId::SneckoSkull,
        h_plus_one as ModifyPowerAmountGivenFn,
    );
    let state = CombatState::default();
    let ctx = crate::hooks::PowerAmountCtx::new(
        None,
        crate::hooks::CreatureRef::Player,
        PowerKind::Poison,
        3,
    );
    assert_eq!(dispatch_modify_power_amount_given(&state, &ctx), 4);
    // Cleanup so cross-test pollution doesn't change the empty-bus
    // assertion above on re-runs.
    registry_modify_power_amount_given().remove(RelicId::SneckoSkull);
}

/// `modify_power_amount_received` listener doubles the amount —
/// RuinedHelmet's `first Str gain *= 2` shape. Chain semantics
/// match the given-side path; this smoke confirms the receiver-side
/// dispatcher uses the same fold convention.
#[test]
#[serial_test::serial(global_registry)]
fn modify_power_amount_received_listener_modifies_amount() {
    fn h_double(_state: &CombatState, ctx: &crate::hooks::PowerAmountCtx) -> i32 {
        ctx.amount.saturating_mul(2)
    }
    register_modify_power_amount_received(
        RelicId::RuinedHelmet,
        h_double as ModifyPowerAmountReceivedFn,
    );
    let state = CombatState::default();
    let ctx = crate::hooks::PowerAmountCtx::new(
        None,
        crate::hooks::CreatureRef::Player,
        PowerKind::Strength,
        7,
    );
    assert_eq!(dispatch_modify_power_amount_received(&state, &ctx), 14);
    registry_modify_power_amount_received().remove(RelicId::RuinedHelmet);
}

/// Bead `sts2-rs-16xxf`: when a `modify_power_amount_received`
/// listener folds the amount to ≤ 0, the surface that consumes
/// the chain (`apply_power_to_creature` at
/// crates/sts2-core/src/card_effects.rs:266) must short-circuit
/// BEFORE the stack/push branch. This test asserts the chain
/// itself returns ≤ 0 under a synthetic listener — pinning the
/// guard's input invariant; the apply-side short-circuit is
/// tested indirectly via the existing x3ql3 + kand1 suites
/// (post-modify amount <= 0 path takes the same `return`
/// branch as the entry-amount <= 0 path covered by x3ql3).
#[test]
#[serial_test::serial(global_registry)]
fn fr16xxf_modify_chain_returns_non_positive_for_synthetic_zero_listener() {
    fn h_zero_out(_state: &CombatState, _ctx: &crate::hooks::PowerAmountCtx) -> i32 {
        -1000
    }
    ensure_installed();
    register_modify_power_amount_received(
        RelicId::RuinedHelmet,
        h_zero_out as ModifyPowerAmountReceivedFn,
    );
    let state = CombatState::default();
    let ctx = crate::hooks::PowerAmountCtx::new(
        None,
        crate::hooks::CreatureRef::Player,
        PowerKind::Strength,
        5,
    );
    let out = dispatch_modify_power_amount_received(&state, &ctx);
    assert!(
        out <= 0,
        "synthetic listener must drive the chain to <= 0 (got {out})",
    );
    // Cleanup: drop the synthetic, then re-install production wiring.
    registry_modify_power_amount_received().remove(RelicId::RuinedHelmet);
    ensure_installed();
}

/// Observer channels (`before_power_amount_changed` +
/// `after_modifying_power_amount_given/_received`) fire and return
/// `Resolved` when a registered listener resolves. Verifies the
/// EffectResult convention matches the existing
/// `dispatch_after_damage_received` precedent.
#[test]
#[serial_test::serial(global_registry)]
fn power_amount_observer_channels_dispatch_resolved() {
    fn h_resolved(_state: &mut CombatState, _ctx: &crate::hooks::PowerAmountCtx) -> EffectResult {
        EffectResult::Resolved
    }
    register_before_power_amount_changed(
        RelicId::UnsettlingLamp,
        h_resolved as BeforePowerAmountChangedFn,
    );
    register_after_modifying_power_amount_given(
        RelicId::SneckoSkull,
        h_resolved as AfterModifyingPowerAmountGivenFn,
    );
    register_after_modifying_power_amount_received(
        RelicId::RuinedHelmet,
        h_resolved as AfterModifyingPowerAmountReceivedFn,
    );
    let mut state = CombatState::default();
    let ctx = crate::hooks::PowerAmountCtx::new(
        None,
        crate::hooks::CreatureRef::Player,
        PowerKind::Strength,
        1,
    );
    assert_eq!(
        dispatch_before_power_amount_changed(&mut state, &ctx),
        EffectResult::Resolved
    );
    assert_eq!(
        dispatch_after_modifying_power_amount_given(&mut state, &ctx),
        EffectResult::Resolved
    );
    assert_eq!(
        dispatch_after_modifying_power_amount_received(&mut state, &ctx),
        EffectResult::Resolved
    );
    registry_before_power_amount_changed().remove(RelicId::UnsettlingLamp);
    registry_after_modifying_power_amount_given().remove(RelicId::SneckoSkull);
    registry_after_modifying_power_amount_received().remove(RelicId::RuinedHelmet);
}

/// Bead `sts2-rs-lcje` — SneckoSkull integration test through the
/// real `install_default_registry` path. Asserts the channel-infra
/// landed by 47jv routes a Poison-given amount through the
/// SneckoSkull `+1` arm only when the player owns the relic and
/// only for `Poison` (other powers pass through unchanged). Uses
/// `apply_power_to_enemy` to drive the canonical card-effect
/// entrypoint so this also smoke-tests the
/// `pipe_power_amount_through_modify_chain` wiring.
#[test]
#[serial_test::serial(global_registry)]
fn snecko_skull_adds_one_to_poison_given() {
    use crate::cards::CardType;
    use std::num::NonZeroU32;
    ensure_installed();
    // Defensive re-registration: the 47jv smoke tests above mutate
    // the global registry and `.remove()` their entries on
    // teardown, which can stomp the canonical SneckoSkull arm when
    // tests run in parallel (ensure_installed uses OnceLock —
    // install_default_registry runs at most once per process).
    register_modify_power_amount_given(
        RelicId::SneckoSkull,
        on_modify_power_amount_given_snecko_skull as ModifyPowerAmountGivenFn,
    );

    // Build a minimal state: 1 player creature + 1 enemy creature.
    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    let enemy_uid = CreatureUid::new(2).unwrap();
    state.creatures.push(crate::Creature {
        id: player_uid.0,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: None,
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId(""),
        ai: None,
    });
    state.creatures.push(crate::Creature {
        id: enemy_uid.0,
        current_hp: 40,
        max_hp: 40,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(crate::MonsterKind::Nibbit),
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId("Nibbit"),
        ai: None,
    });
    state.player.creature_uid = Some(player_uid);
    // Suppress unused-import warning in case the CardType bring-in
    // is not needed by a future refactor; the explicit `_` keeps
    // the import meaningful at the call site below.
    let _ = CardType::Attack;
    let _ = NonZeroU32::new(1).unwrap();

    // Case 1: no relic — Poison applies at the base amount.
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_uid, crate::PowerKind::Poison, 3);
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Poison),
        3,
        "no relic → no bonus"
    );

    // Reset target's Poison stack and equip SneckoSkull.
    clear_creature_powers(&mut state, enemy_uid);
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::SneckoSkull,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });

    // Case 2: relic owned, Poison given — amount + 1.
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_uid, crate::PowerKind::Poison, 3);
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Poison),
        4,
        "SneckoSkull adds EXTRA_POISON (=1) to Poison given"
    );

    // Case 3: relic owned, non-Poison given — no bonus.
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_uid, crate::PowerKind::Weak, 2);
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Weak),
        2,
        "SneckoSkull arm gates on PowerKind::Poison"
    );

    // Case 4: stack into existing Poison — bonus applies per call.
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_uid, crate::PowerKind::Poison, 5);
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Poison),
        4 + 6,
        "second Poison application adds 5+1 on top of existing 4"
    );
}

/// **v0.107.1 give-side power-mod split (`§1a.10`, bead `…wb8lk.1`).** v0.107.1
/// bifurcated the single `ModifyPowerAmountGiven` hook into
/// `…GivenAdditive` (SneckoSkull, +1 Poison) and `…GivenMultiplicative`
/// (UnsettlingLamp, ×2 debuffs), making the combine deterministic:
/// `(base + Σ additives) × Π multiplicatives`. The Rust engine keeps a single
/// left-to-right fold, but it walks listeners in `RelicId` order — and
/// `SneckoSkull` (additive) sorts BEFORE `UnsettlingLamp` (multiplicative), so
/// the fold reproduces v0.107.1's additive-then-multiplicative result. This
/// test pins that ordering: a Poison(3) given with BOTH relics resolves to
/// `(3 + 1) × 2 = 8`, NOT the reversed `3 × 2 + 1 = 7`. A future `RelicId`
/// reshuffle that put UnsettlingLamp first would break this and silently
/// diverge from v0.107.1.
#[test]
#[serial_test::serial(global_registry)]
fn snecko_skull_then_unsettling_lamp_fold_is_additive_then_multiplicative() {
    use std::num::NonZeroU32;
    ensure_installed();
    // Defensive re-registration (see snecko_skull_adds_one_to_poison_given):
    // the 47jv smoke tests `.remove()` these arms on teardown.
    register_modify_power_amount_given(
        RelicId::SneckoSkull,
        on_modify_power_amount_given_snecko_skull as ModifyPowerAmountGivenFn,
    );
    register_modify_power_amount_given(
        RelicId::UnsettlingLamp,
        on_modify_power_amount_given_unsettling_lamp as ModifyPowerAmountGivenFn,
    );

    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    let enemy_uid = CreatureUid::new(2).unwrap();
    state.player.creature_uid = Some(player_uid);
    state.creatures.push(crate::Creature {
        id: player_uid.0,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: None,
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId(""),
        ai: None,
    });
    state.creatures.push(crate::Creature {
        id: enemy_uid.0,
        current_hp: 40,
        max_hp: 40,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: Some(crate::MonsterKind::Nibbit),
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId("Nibbit"),
        ai: None,
    });

    // Equip both relics. UnsettlingLamp is forced to CAPTURED so its
    // doubling arm is live (bypasses the arm/finish state machine, which is
    // covered separately).
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::SneckoSkull,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(2).unwrap(),
        kind: crate::RelicKind::UnsettlingLamp,
        counter: UNSETTLING_LAMP_CAPTURED,
        is_wax: false,
        is_melted: false,
    });

    // The lamp only doubles CARD-driven applications (GH #365), so the ctx
    // has to name one -- `PowerAmountCtx::new` hardcodes `source_card: None`.
    let ctx = crate::hooks::PowerAmountCtx {
        source_card: Some(push_resolving_card(&mut state)),
        ..crate::hooks::PowerAmountCtx::new(
            Some(crate::hooks::CreatureRef::Player),
            crate::hooks::CreatureRef::Enemy(enemy_uid),
            crate::PowerKind::Poison,
            3,
        )
    };
    assert_eq!(
        dispatch_modify_power_amount_given(&state, &ctx),
        8,
        "additive (SneckoSkull +1) folds before multiplicative (UnsettlingLamp ×2): (3+1)×2"
    );
}

/// GH #1150 — once captured, the Lamp doubles a debuff from the capturing
/// card whatever its applier: C# `ModifyPowerAmountGivenMultiplicative`
/// compares only `cardSource` (Misery copying a monster-applied debuff after a
/// player-applied copy captured the trigger). The capture arm still needs the
/// player as applier.
#[test]
#[serial_test::serial(global_registry)]
fn unsettling_lamp_doubles_a_monster_applied_copy_once_captured() {
    use std::num::NonZeroU32;
    ensure_installed();
    register_before_power_amount_changed(
        RelicId::UnsettlingLamp,
        on_before_power_amount_changed_unsettling_lamp as BeforePowerAmountChangedFn,
    );
    register_modify_power_amount_given(
        RelicId::UnsettlingLamp,
        on_modify_power_amount_given_unsettling_lamp as ModifyPowerAmountGivenFn,
    );
    let mut state = CombatState::default();
    let enemy_a = CreatureUid::new(2).unwrap();
    let enemy_b = CreatureUid::new(3).unwrap();
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::UnsettlingLamp,
        counter: UNSETTLING_LAMP_ARMED,
        is_wax: false,
        is_melted: false,
    });
    let card = push_resolving_card(&mut state);
    let monster_copy = crate::hooks::PowerAmountCtx {
        source_card: Some(card),
        ..crate::hooks::PowerAmountCtx::new(
            Some(crate::hooks::CreatureRef::Enemy(enemy_a)),
            crate::hooks::CreatureRef::Enemy(enemy_b),
            crate::PowerKind::Weak,
            2,
        )
    };
    // Armed: a monster-applied copy neither captures nor is doubled.
    assert_eq!(
        on_before_power_amount_changed_unsettling_lamp(&mut state, &monster_copy),
        EffectResult::NotImplemented
    );
    assert_eq!(unsettling_lamp_state(&state), Some(UNSETTLING_LAMP_ARMED));
    assert_eq!(dispatch_modify_power_amount_given(&state, &monster_copy), 2);
    // A player-applied copy captures the trigger ...
    let player_copy = crate::hooks::PowerAmountCtx {
        applier: Some(crate::hooks::CreatureRef::Player),
        ..monster_copy
    };
    let _ = on_before_power_amount_changed_unsettling_lamp(&mut state, &player_copy);
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_CAPTURED)
    );
    // ... and from then on the monster-applied copy is doubled too.
    assert_eq!(dispatch_modify_power_amount_given(&state, &monster_copy), 4);
}

/// GH #365 — a POTION's debuff must neither be doubled nor burn the lamp's
/// once-per-combat trigger.
///
/// C# `UnsettlingLamp.BeforePowerAmountChanged` bails on `cardSource == null`
/// (`UnsettlingLamp.cs:80-83`); Rust had no card-source gate, so a potion
/// captured the trigger, got doubled itself, and left the real trigger card
/// undoubled. Measured on the 2026-08-03 live Silent A1 corpus —
/// WaterfallGiant POISON mirror 12 / world 6 (the potion applies 6), then
/// VULNERABLE 1 vs 2 on the very next play, the burnt trigger. This test is
/// that exact sequence.
#[test]
#[serial_test::serial(global_registry)]
fn unsettling_lamp_ignores_a_potions_debuff_and_keeps_its_trigger() {
    use std::num::NonZeroU32;
    ensure_installed();
    register_before_power_amount_changed(
        RelicId::UnsettlingLamp,
        on_before_power_amount_changed_unsettling_lamp as BeforePowerAmountChangedFn,
    );
    register_modify_power_amount_given(
        RelicId::UnsettlingLamp,
        on_modify_power_amount_given_unsettling_lamp as ModifyPowerAmountGivenFn,
    );

    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    let enemy_uid = CreatureUid::new(2).unwrap();
    for (uid, hp) in [(player_uid, 80_i32), (enemy_uid, 50)] {
        state.creatures.push(crate::Creature {
            id: uid.0,
            current_hp: hp,
            max_hp: hp,
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: None,
            intent: None,
            intent_history: crate::IntentHistory::default(),
            monster_id: crate::MonsterId(""),
            ai: None,
        });
    }
    state.player.creature_uid = Some(player_uid);
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::UnsettlingLamp,
        counter: UNSETTLING_LAMP_ARMED,
        is_wax: false,
        is_melted: false,
    });

    // A potion: nothing on the play pile, so `resolving_card` is None — the
    // same shape C# hands the lamp as `cardSource: null`.
    assert!(state.player.play.is_empty(), "no card is resolving");
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_uid, crate::PowerKind::Poison, 6);
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Poison),
        6,
        "the potion's Poison is NOT doubled (was 12 pre-fix)"
    );
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_ARMED),
        "and the once-per-combat trigger is still unspent"
    );

    // Now the real trigger: a card. It captures and doubles.
    let _resolving = push_resolving_card(&mut state);
    crate::card_effects::apply_power_to_enemy(
        &mut state,
        enemy_uid,
        crate::PowerKind::Vulnerable,
        1,
    );
    assert_eq!(
        enemy_power_amount(&state, enemy_uid, crate::PowerKind::Vulnerable),
        2,
        "the CARD's debuff is the one that gets doubled (was 1 pre-fix — the \
         potion had burnt the trigger)"
    );
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_CAPTURED),
        "the card is what spent the trigger"
    );
}

