/// Put a card on the play pile so power applications read as card-driven.
///
/// GH #365: UnsettlingLamp is gated on C#'s `cardSource` argument, which Rust
/// derives from the play pile (`card_effects::resolving_card`). A test that
/// calls `apply_power_to_enemy` with an empty play pile is modelling a
/// POTION / power tick, not a card — and the lamp must ignore those. Every
/// lamp fixture that means "a card is resolving" has to say so.
fn push_resolving_card(state: &mut CombatState) -> crate::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("u32");
    let uid = crate::CardUid::new(raw).expect("nz");
    state.cards.push(crate::cards::Card {
        uid,
        card_id: crate::cards::CardId::StrikeIronclad,
        cost: 1,
        card_type: crate::cards::CardType::Attack,
        target_type: crate::cards::TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..crate::cards::Card::pod_defaults()
    });
    state.player.play.push(uid);
    uid
}

fn clear_creature_powers(state: &mut CombatState, uid: CreatureUid) {
    let Some(c) = state.creatures.iter_mut().find(|c| c.id == uid.0) else {
        return;
    };
    let uids: Vec<_> = c.powers.iter().copied().collect();
    c.powers.clear();
    state.powers.retain(|p| !uids.iter().any(|u| u.0 == p.id));
}

/// Bead `sts2-rs-npg1` — RuinedHelmet integration test through
/// `apply_power_to_creature`. Asserts:
///   * first positive Strength gain → doubled,
///   * second Strength gain in the same combat → unchanged,
///   * Dexterity gain (any time) → unchanged,
///   * `after_combat_end` re-arms the relic for the next combat.
#[test]
#[serial_test::serial(global_registry)]
fn ruined_helmet_doubles_first_strength_then_resets_at_combat_end() {
    use std::num::NonZeroU32;
    ensure_installed();
    // Defensive re-registration — see snecko_skull_adds_one_to_poison_given
    // for the parallel-test-pollution rationale.
    register_modify_power_amount_received(
        RelicId::RuinedHelmet,
        on_modify_power_amount_received_ruined_helmet as ModifyPowerAmountReceivedFn,
    );
    register_after_modifying_power_amount_received(
        RelicId::RuinedHelmet,
        on_after_modifying_power_amount_received_ruined_helmet
            as AfterModifyingPowerAmountReceivedFn,
    );
    register_after_combat_end(
        RelicId::RuinedHelmet,
        on_after_combat_end_ruined_helmet as AfterCombatEndFn,
    );

    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    state.creatures.push(crate::Creature {
        id: player_uid.0,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: smallvec::SmallVec::new(),
        species: None,
        intent: None,
        intent_history: crate::IntentHistory::default(),
        monster_id: crate::MonsterId(""),
        ai: None,
    });
    state.player.creature_uid = Some(player_uid);
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::RuinedHelmet,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });

    // First +1 Strength → doubled to +2.
    crate::card_effects::apply_power_to_creature(
        &mut state,
        player_uid,
        crate::PowerKind::Strength,
        1,
    );
    assert_eq!(
        enemy_power_amount(&state, player_uid, crate::PowerKind::Strength),
        2,
        "first Strength gain doubled (1 → 2)"
    );
    assert_eq!(
        state
            .relics
            .iter()
            .find(|r| r.kind == crate::RelicKind::RuinedHelmet)
            .expect("relic present")
            .counter,
        1,
        "UsedThisCombat flag set after doubling"
    );

    // Second +3 Strength → unchanged (already used this combat).
    crate::card_effects::apply_power_to_creature(
        &mut state,
        player_uid,
        crate::PowerKind::Strength,
        3,
    );
    assert_eq!(
        enemy_power_amount(&state, player_uid, crate::PowerKind::Strength),
        2 + 3,
        "second Strength gain not doubled — adds 3 on top of doubled 2"
    );

    // Dexterity gain — unaffected even though Strength was the
    // previous arm trigger.
    crate::card_effects::apply_power_to_creature(
        &mut state,
        player_uid,
        crate::PowerKind::Dexterity,
        4,
    );
    assert_eq!(
        enemy_power_amount(&state, player_uid, crate::PowerKind::Dexterity),
        4,
        "Dexterity gain gates fail on power_kind check"
    );

    // Simulate after_combat_end — flag resets to 0.
    let _ = dispatch_after_combat_end(&mut state);
    assert_eq!(
        state
            .relics
            .iter()
            .find(|r| r.kind == crate::RelicKind::RuinedHelmet)
            .expect("relic present")
            .counter,
        0,
        "after_combat_end clears UsedThisCombat flag"
    );

    // Clear the player's existing Strength stack so the next
    // assertion starts fresh (we want to observe the new
    // application's contribution in isolation).
    clear_creature_powers(&mut state, player_uid);

    // Next combat (after reset) — Strength gain doubles again.
    crate::card_effects::apply_power_to_creature(
        &mut state,
        player_uid,
        crate::PowerKind::Strength,
        2,
    );
    assert_eq!(
        enemy_power_amount(&state, player_uid, crate::PowerKind::Strength),
        4,
        "after combat_end reset, first Strength gain doubled again (2 → 4)"
    );
}

/// Bead `sts2-rs-7uo4` — UnsettlingLamp 3-state machine through
/// `apply_power_to_enemy` + `dispatch_after_card_played`. Asserts
/// the capture / double / finish / reset cycle.
#[test]
#[serial_test::serial(global_registry)]
fn unsettling_lamp_doubles_first_card_debuffs_then_finishes() {
    use std::num::NonZeroU32;
    ensure_installed();
    // Defensive re-registration — see snecko_skull / ruined_helmet
    // tests for the parallel-test-pollution rationale.
    register_before_power_amount_changed(
        RelicId::UnsettlingLamp,
        on_before_power_amount_changed_unsettling_lamp as BeforePowerAmountChangedFn,
    );
    register_modify_power_amount_given(
        RelicId::UnsettlingLamp,
        on_modify_power_amount_given_unsettling_lamp as ModifyPowerAmountGivenFn,
    );
    register_after_card_played(
        RelicId::UnsettlingLamp,
        on_after_card_played_unsettling_lamp as AfterCardPlayedFn,
    );
    register_after_combat_end(
        RelicId::UnsettlingLamp,
        on_after_combat_end_unsettling_lamp as AfterCombatEndFn,
    );

    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    let enemy_a = CreatureUid::new(2).unwrap();
    let enemy_b = CreatureUid::new(3).unwrap();
    for (uid, hp) in [(player_uid, 80_i32), (enemy_a, 50), (enemy_b, 50)] {
        state.creatures.push(crate::Creature {
            id: uid.0,
            current_hp: hp,
            max_hp: hp,
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: None,
            intent: None,
            intent_history: crate::IntentHistory::default(),
            monster_id: crate::MonsterId(""),
            ai: None,
        });
    }
    state.player.creature_uid = Some(player_uid);
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: crate::RelicKind::UnsettlingLamp,
        counter: UNSETTLING_LAMP_ARMED,
        is_wax: false,
        is_melted: false,
    });
    // A card is resolving -- without one these applications read as a potion
    // and the lamp correctly ignores them (GH #365).
    let _resolving = push_resolving_card(&mut state);

    // First card scope: apply Vulnerable 2 to enemy_a, then Weak 1
    // to enemy_b. Both should be doubled — capture fires on the
    // first apply, then modify doubles every subsequent eligible
    // debuff while counter sits at CAPTURED.
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_a, crate::PowerKind::Vulnerable, 2);
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_b, crate::PowerKind::Weak, 1);
    assert_eq!(
        enemy_power_amount(&state, enemy_a, crate::PowerKind::Vulnerable),
        4,
        "first card's Vulnerable on enemy_a doubled (2 → 4)"
    );
    assert_eq!(
        enemy_power_amount(&state, enemy_b, crate::PowerKind::Weak),
        2,
        "same card's Weak on enemy_b also doubled (1 → 2)"
    );
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_CAPTURED),
        "still in CAPTURED scope until after_card_played fires"
    );

    // First card finishes — after_card_played advances to FINISHED.
    let card_ctx = CardEventCtx {
        card_id: crate::cards::CardId::StrikeIronclad,
        card_uid: None,
        target: Some(enemy_a),
        card_tags: crate::cards::CardTags::default(),
        energy_spent: 0,
    };
    let _ = dispatch_after_card_played(&mut state, &card_ctx);
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_FINISHED),
        "after_card_played advances CAPTURED → FINISHED"
    );

    // Second card scope: Vulnerable 3 to enemy_a — should NOT
    // double (relic is finished for this combat).
    crate::card_effects::apply_power_to_enemy(&mut state, enemy_a, crate::PowerKind::Vulnerable, 3);
    assert_eq!(
        enemy_power_amount(&state, enemy_a, crate::PowerKind::Vulnerable),
        4 + 3,
        "second card's Vulnerable not doubled — stacks 3 on top of 4"
    );

    // after_combat_end re-arms.
    let _ = dispatch_after_combat_end(&mut state);
    assert_eq!(
        unsettling_lamp_state(&state),
        Some(UNSETTLING_LAMP_ARMED),
        "after_combat_end re-arms the relic"
    );
}

/// v0.107.1 `PowerCmd.Apply` fires `BeforePowerAmountChanged` BEFORE
