// -----------------------------------------------------------------
// Deep tests — PaelsTears (sts2-rs-hjs6k)
//
// Per-turn leftover-energy latch on `Relic.counter`. Player turn-end
// with `player.energy > 0` → counter=1; next player turn-start
// consumes the latch and grants +2 energy. Enemy-side hooks no-op;
// no leftover at turn-end → no bonus.
// -----------------------------------------------------------------

fn paels_tears_counter(state: &CombatState) -> i32 {
    state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::PaelsTears)
        .expect("PaelsTears relic present")
        .counter
}

/// Player turn-end with leftover energy latches counter = 1.
