/// Fiddle's OTHER half: it vetoes card-effect draws on its owner's own side
/// (`Fiddle.cs:24-38` `ShouldDraw`). Only the `+2` was ported, so a Battle
/// Trance / Pommel Strike under Fiddle drew cards the real game refused — the
/// DLL mirror's largest pure-draw divergence class on the v11 sweep was 288
/// records holding the SAME cards split differently between hand and draw,
/// with Fiddle at a 5.1x lift over its baseline rate.
#[test]
#[serial_test::serial(global_registry)]
fn fiddle_vetoes_a_card_effect_draw_on_the_players_own_turn() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    state.side = crate::Side::Player;
    for i in 0..4u32 {
        let uid = crate::CardUid::new(i + 1).expect("nz");
        state.cards.push(crate::cards::Card {
            uid,
            card_id: crate::cards::CardId::StrikeIronclad,
            cost: 1,
            card_type: crate::cards::CardType::Attack,
            target_type: crate::cards::TargetType::Enemy,
            ..crate::cards::Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }

    assert_eq!(
        crate::cards::draw_via_state(&mut state, 2),
        2,
        "without Fiddle a card-effect draw goes through"
    );

    give_player_relic(&mut state, RelicKind::Fiddle);
    assert_eq!(
        crate::cards::draw_via_state(&mut state, 2),
        0,
        "with Fiddle, on the player's own side, it is vetoed"
    );

    // The veto is scoped to the owner's side: C# allows the draw when the
    // acting side is not the owner's.
    state.side = crate::Side::Enemy;
    assert_eq!(
        crate::cards::draw_via_state(&mut state, 1),
        1,
        "off the player's side Fiddle does not veto"
    );
}

/// No round gate — Fiddle fires the same at round 1 and round 7.
#[test]
#[serial_test::serial(global_registry)]
fn fiddle_no_round_gate() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::Fiddle);
    for r in [1u16, 2, 3, 7] {
        state.round = r;
        assert_eq!(dispatch_modify_hand_draw(&state, 5), 7, "round {r}");
    }
}

