// ── GalacticDust (sts2-rs-ok4t) ───────────────────────────────────────
// REGENT-pool uncommon: accumulate stars spent on `Relic.counter`;
// every 10 stars → +10 block (unpowered). Threshold-loop, so a
// single large spend can fire multiple block gains.

fn galactic_dust_counter(state: &CombatState) -> i32 {
    state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::GalacticDust)
        .map_or(-1, |r| r.counter)
}

fn install_galactic_dust(state: &mut CombatState) {
    use std::num::NonZeroU32;
    state.relics.push(crate::Relic {
        id: NonZeroU32::new(42).unwrap(),
        kind: RelicKind::GalacticDust,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
}

#[test]
#[serial_test::serial(global_registry)]
fn galactic_dust_accumulates_below_threshold_no_block() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    install_galactic_dust(&mut state);
    let ctx = crate::hooks::StarsSpentCtx { amount: 7 };

    let result = dispatch_on_stars_spent(&mut state, &ctx);
    assert_eq!(result, EffectResult::Resolved);
    assert_eq!(state.player.block, 0, "no block below threshold");
    assert_eq!(galactic_dust_counter(&state), 7, "counter accumulates");
}

#[test]
#[serial_test::serial(global_registry)]
fn galactic_dust_threshold_crossing_grants_block_and_resets() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    install_galactic_dust(&mut state);
    // First spend: 7 stars (no fire).
    let _ = dispatch_on_stars_spent(&mut state, &crate::hooks::StarsSpentCtx { amount: 7 });
    // Second spend: 5 stars → total 12, crosses 10 → 1 trigger,
    // counter back to 2.
    let _ = dispatch_on_stars_spent(&mut state, &crate::hooks::StarsSpentCtx { amount: 5 });
    assert_eq!(state.player.block, 10, "+10 block on threshold cross");
    assert_eq!(galactic_dust_counter(&state), 2, "counter wraps via -10");
}

#[test]
#[serial_test::serial(global_registry)]
fn galactic_dust_multi_trigger_single_big_spend() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    install_galactic_dust(&mut state);
    // 25 stars at once → 2 triggers (+20 block), counter = 5.
    let _ = dispatch_on_stars_spent(&mut state, &crate::hooks::StarsSpentCtx { amount: 25 });
    assert_eq!(state.player.block, 20, "two triggers from single spend");
    assert_eq!(galactic_dust_counter(&state), 5, "remainder retained");
}

