// Issue #50 — TheCourier / EmotionChip / GamblingChip tests.
// -----------------------------------------------------------------

/// Invokes the registered `TheCourier` shop-price listener directly
/// (bypassing the fold) so the assertion is independent of other
/// listeners that may have been installed by sibling tests on the
/// process-global registry. Bead-style isolation pattern from
/// `count_pets_bound_phylactery_production_listener`.
#[test]
#[serial_test::serial(global_registry)]
fn the_courier_discounts_shop_price_by_20pct() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let ctx = ShopPriceCtx {
        item_kind: ShopItemKind::Card,
    };
    let listener = lookup_modify_shop_price(RelicId::TheCourier)
        .expect("TheCourier shop-price listener must be installed");
    // No relic owned: passthrough.
    assert_eq!(listener(&state, &ctx, 100), 100, "ungated -> passthrough");
    give_player_relic(&mut state, RelicKind::TheCourier);
    assert_eq!(
        listener(&state, &ctx, 100),
        80,
        "TheCourier must trim 20% off the running shop price"
    );
    assert_eq!(
        listener(&state, &ctx, 50),
        40,
        "50 - (50 * 20 / 100) = 40 (floor-div mirror of Python `//`)"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn the_courier_inert_without_relic() {
    ensure_installed();
    let state = fresh_state_with_player(80, 80);
    let ctx = ShopPriceCtx {
        item_kind: ShopItemKind::Card,
    };
    let listener = lookup_modify_shop_price(RelicId::TheCourier)
        .expect("TheCourier shop-price listener must be installed");
    assert_eq!(
        listener(&state, &ctx, 100),
        100,
        "no relic -> no discount applied"
    );
}

#[test]
#[serial_test::serial(global_registry)]
fn emotion_chip_triggers_passive_on_prior_hp_loss() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::EmotionChip);
    // Use Frost so passive_tick is observable purely on
    // `player.block` (no enemy roster needed).
    crate::orbs::channel_orb(&mut state, crate::orbs::Orb::frost());
    let block_before = state.player.block;
    // Simulate HP loss "last turn": bump the counter directly.
    for r in &mut state.relics {
        if r.kind == RelicKind::EmotionChip {
            r.counter = 5;
        }
    }
    let _ = dispatch_after_player_turn_start(&mut state);
    assert!(
        state.player.block > block_before,
        "EmotionChip must fire orb passives (Frost grants block) when HP was lost last turn"
    );
    // Counter consumed -> 0.
    let counter = state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::EmotionChip)
        .map_or(-1, |r| r.counter);
    assert_eq!(counter, 0, "counter must reset after firing");
}

fn emotion_chip_counter_after_hit(block: i32, buffer: bool, damage: i32) -> i32 {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::EmotionChip);
    state.player.block = block;
    if buffer {
        state.powers.push(crate::Power {
            id: NonZeroU32::new(9001).unwrap(),
            kind: crate::PowerKind::Buffer,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state
            .player
            .powers
            .push(crate::PowerUid(NonZeroU32::new(9001).unwrap()));
    }
    let _ = crate::combat_loop::apply_damage_to_player(
        &mut state,
        crate::hooks::CreatureRef::Nobody,
        damage,
        crate::hooks::ValueProps::NONE,
        None,
    );
    state
        .relics
        .iter()
        .find(|r| r.kind == RelicKind::EmotionChip)
        .map_or(-1, |r| r.counter)
}

/// C# `LostHpInPreviousTurn` keys on a `DamageReceivedEntry` that was not
/// `WasFullyBlocked` (EmotionChip.cs:14): an unblocked hit Buffer zeroes still
/// arms it, a hit block fully absorbs does not, and a killing blow does
/// (loadout Defect v0.107.1 2033).
#[test]
#[serial_test::serial(global_registry)]
fn emotion_chip_arms_on_a_not_fully_blocked_hit_not_on_hp_loss() {
    assert!(
        emotion_chip_counter_after_hit(0, true, 6) > 0,
        "Buffer-zeroed hit at 0 block arms EmotionChip"
    );
    assert_eq!(
        emotion_chip_counter_after_hit(10, false, 6),
        0,
        "a hit fully absorbed by block does not arm it"
    );
    assert!(
        emotion_chip_counter_after_hit(0, false, 200) > 0,
        "a killing blow still records its damage entry"
    );
}

/// EmotionChip armed (HP lost last turn) with Gold-Plated Cables and the given
/// orbs, fired once at player turn start under `version`.
fn emotion_chip_with_cables_fired(
    version: crate::GameVersion,
    orbs: &[crate::orbs::Orb],
) -> CombatState {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    state.game_version = version;
    give_player_relic(&mut state, RelicKind::EmotionChip);
    give_player_relic(&mut state, RelicKind::GoldPlatedCables);
    state.player.orbs = crate::orbs::OrbSlots::with_default_capacity();
    for &orb in orbs {
        crate::orbs::channel_orb(&mut state, orb);
    }
    for r in &mut state.relics {
        if r.kind == RelicKind::EmotionChip {
            r.counter = 5;
        }
    }
    let _ = dispatch_after_player_turn_start(&mut state);
    state
}

