#[test]
#[serial_test::serial(global_registry)]
fn gambling_chip_round_1_opens_discard_and_draw_choice() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::GamblingChip);
    // C# GamblingChip.AfterPlayerTurnStart (v0.107.1): an INTERACTIVE
    // FromHandForDiscard(prefs(0, inf)) select over the opening hand,
    // then DiscardAndDraw(list, list.Count) -- NOT an auto-discard of
    // the whole hand (shadow census v8 seeds 1004/1047).
    let mk_card = |uid_val: u32| crate::Card {
        uid: crate::CardUid(std::num::NonZeroU32::new(uid_val).unwrap()),
        card_id: crate::cards::CardId::StrikeIronclad,
        cost: 1,
        card_type: crate::cards::CardType::Attack,
        target_type: crate::cards::TargetType::Enemy,
        upgraded: false,
        base_damage: 6,
        base_block: 0,
        ..crate::Card::pod_defaults()
    };
    for uid_val in 1001..=1002 {
        state.cards.push(mk_card(uid_val));
        state
            .player
            .hand
            .push(crate::CardUid(std::num::NonZeroU32::new(uid_val).unwrap()));
    }
    let hand_before: Vec<crate::CardUid> = state.player.hand.iter().copied().collect();
    // C# channel is `AfterPlayerTurnStart` (`CombatManager.SetupPlayerTurn`),
    // NOT the outer loop's `AfterSideTurnStart` — mirror-fidelity defect #13.
    let suspended = dispatch_after_player_turn_start(&mut state);
    assert_eq!(
        suspended,
        Some(1),
        "the blocking mulligan screen must suspend the relic walk after \
         GamblingChip's equip slot"
    );
    // The hand is untouched until the player resolves the select.
    assert_eq!(
        state.player.hand.as_slice(),
        hand_before.as_slice(),
        "hand must be untouched until the choice resolves"
    );
    let pc = state
        .pending_choice
        .as_ref()
        .expect("GamblingChip must open a pending choice at round-1 turn start");
    assert_eq!(pc.kind, crate::ChoiceKind::DiscardFromHandAndDraw);
    assert_eq!(pc.min_select, 0, "choose-any: min 0");
    assert_eq!(
        pc.options.len(),
        hand_before.len(),
        "one option per hand card"
    );
    for (opt, uid) in pc.options.iter().zip(hand_before.iter()) {
        assert_eq!(opt.card_uid, Some(*uid));
    }
}

