/// Mirror-fidelity round-4 defect #13: GamblingChip's round-1 mulligan is an
/// `await`ed `CardSelectCmd` inside C# `Hook.AfterPlayerTurnStart`
/// (`GamblingChip.cs` + `CombatManager.SetupPlayerTurn:677`), so the whole
/// remainder of the setup task blocks on it:
///   * later `AfterPlayerTurnStart` relics — MercuryHourglass's 3 to all
///     (`MercuryHourglass.cs`),
///   * the `AfterPlayerTurnStartLate` pass — BloodVial's heal 2
///     (`BloodVial.cs`),
///   * the phase advance to the play phase.
///
/// None of those may have run while the screen is open; all of them must run
/// once it resolves (18 v34wr records, seeds 1004 / 1047).
///
/// The outer loop's `Hook.AfterSideTurnStart` is NOT behind the screen.
/// `StartTurn` waits on the setup task only until it pauses
/// (`WaitForPauseOrCompletionWithoutAssigningTask`, v0.111.0
/// `CombatManager.cs:779-785`, v0.107.1 `:516-524`) and runs the side walk
/// then. The screen itself waits for that: `SignalPlayerChoiceBegun` awaits
/// `_taskAssignedCompletionSource` (`HookPlayerChoiceContext.cs`), which only
/// `RunAutoPrePlayPhase` sets, after the side walk. So Akabeko's Vigor 8
/// (`Akabeko.cs`) and Lantern's +1 energy (`Lantern.cs`) are already in place
/// when the pick is made, and they do not fire again after it.
#[test]
#[serial_test::serial(global_registry)]
fn gambling_chip_mulligan_defers_the_rest_of_turn_one_setup() {
    use crate::{apply, Action};
    ensure_installed();
    let mut state = fresh_state_with_player(80, 70);
    state.phase = crate::CombatPhase::PlayerTurnStart;
    // EQUIP ORDER is the C# hook-walk order: GamblingChip first, so every
    // relic below it waits behind the screen.
    give_player_relic(&mut state, RelicKind::GamblingChip);
    give_player_relic(&mut state, RelicKind::MercuryHourglass);
    give_player_relic(&mut state, RelicKind::Akabeko);
    give_player_relic(&mut state, RelicKind::Lantern);
    give_player_relic(&mut state, RelicKind::BloodVial);
    let enemy = push_enemy(&mut state, 900, 40);
    for uid_val in 9001..=9003 {
        let uid = crate::CardUid(std::num::NonZeroU32::new(uid_val).expect("non-zero"));
        let mut card = crate::cards::Card::pod_defaults();
        card.uid = uid;
        card.card_id = crate::cards::CardId::StrikeIronclad;
        card.card_type = crate::cards::CardType::Attack;
        state.cards.push(card);
        state.player.hand.push(uid);
    }

    let result = crate::combat_loop::start_player_turn(&mut state);
    assert_eq!(result, crate::StepResult::PendingChoice);
    assert_eq!(
        state
            .pending_choice
            .as_ref()
            .map(|pc| pc.kind)
            .expect("the mulligan screen is open"),
        crate::ChoiceKind::DiscardFromHandAndDraw
    );
    // The rest of turn-1 setup is parked, not run.
    assert!(
        state.pending_cluster_resume.is_some(),
        "the turn-start tail must be parked on the cluster-resume marker"
    );
    assert_eq!(
        player_power_amount(&state, PowerKind::Vigor),
        8,
        "Akabeko's AfterSideTurnStart Vigor runs during the pause"
    );
    assert_eq!(
        enemy_current_hp(&state, enemy),
        40,
        "MercuryHourglass's AfterPlayerTurnStart damage must wait for the pick"
    );
    assert_eq!(
        state.player.current_hp, 70,
        "BloodVial's heal must wait for the pick"
    );
    assert_eq!(
        state.player.energy, 4,
        "energy is reset before the screen; Lantern's +1 runs during the pause"
    );
    assert_eq!(state.phase, crate::CombatPhase::PlayerTurnStart);

    // Skip the mulligan — the deferred batch runs now, in C# order.
    let _ = apply(
        &mut state,
        Action::ResolveChoice {
            selection: smallvec::SmallVec::new(),
        },
    );
    assert!(state.pending_choice.is_none());
    assert!(state.pending_cluster_resume.is_none());
    assert_eq!(player_power_amount(&state, PowerKind::Vigor), 8);
    assert_eq!(enemy_current_hp(&state, enemy), 40 - 3);
    assert_eq!(state.player.current_hp, 72);
    assert_eq!(state.player.energy, 4);
    assert_eq!(state.phase, crate::CombatPhase::PlayerPlayPhase);
}

/// A duplicated selection index discards ONCE and draws per ACTUAL discard.
///
/// Pin for the mirror_d1 "post-mulligan hand short by 1" forensics (seeds
/// 1004/1047): the python driver used to encode the search's FINALIZE/SKIP
/// action as a phantom "choose option 0", producing selections like
/// `[1,3,0,0,2]` with a duplicate. The DLL's `ResolvePendingByIndices`
/// (RunSimulator.cs:7119-7127) resolves ORIGINAL indices and keeps the
/// duplicate, so C# `GamblingChip.AfterPlayerTurnStart` → `CardCmd.
/// DiscardAndDraw(list, list.Count)` (GamblingChip.cs:20-23, CardCmd.cs:
/// 172-197, v0.107.1) received a 5-entry list naming 4 distinct cards: it
/// discarded 4 (the second `CardPileCmd.Add` of an already-discarded card
/// is a no-op) and drew `list.Count` = 5. The engine resolver
/// (`resolve_discard_from_hand_and_draw`) skips the duplicate at the
/// hand-membership check and draws `discarded` = 4 — which matches what
/// the REAL game can produce (its select screen cannot return the same
/// CardModel twice); the duplicate list is a headless-driver artifact,
/// now also outlawed on the python side
/// (`sts2_hint.recommender.choice_picks_from_tags`). This test pins the
/// engine half of that contract so neither side drifts back.
#[test]
#[serial_test::serial(global_registry)]
fn discard_from_hand_and_draw_duplicate_selection_draws_per_actual_discard() {
    use crate::{apply, Action};
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let mk_uid = |raw: u32| crate::CardUid::new(raw).expect("non-zero");
    // 5-card hand (the mulligan screen's option list) + 6-card draw pile.
    for raw in 7001..=7005 {
        let mut card = crate::cards::Card::pod_defaults();
        card.uid = mk_uid(raw);
        card.card_id = crate::cards::CardId::StrikeIronclad;
        card.card_type = crate::cards::CardType::Attack;
        state.cards.push(card);
        state.player.hand.push(mk_uid(raw));
    }
    for raw in 7101..=7106 {
        let mut card = crate::cards::Card::pod_defaults();
        card.uid = mk_uid(raw);
        card.card_id = crate::cards::CardId::DefendIronclad;
        card.card_type = crate::cards::CardType::Skill;
        state.cards.push(card);
        state.player.draw.push(mk_uid(raw));
    }
    let options: Vec<crate::ChoiceOption> = state
        .player
        .hand
        .iter()
        .map(|&uid| crate::ChoiceOption {
            card_id: crate::cards::CardId::StrikeIronclad,
            upgraded: false,
            card_uid: Some(uid),
            source_pile: Some(crate::cards::PileKind::Hand),
        })
        .collect();
    state.request_card_choice(
        crate::ChoiceKind::DiscardFromHandAndDraw,
        options,
        0,
        5,
        true,
    );

    // The corpus selection verbatim: options 1, 3, 0, 0 (duplicate), 2 —
    // four distinct cards, option 4 kept. Len >= 2 takes the atomic
    // back-compat path straight into the kind-resolver.
    let selection: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::from_slice(&[1, 3, 0, 0, 2]);
    let _ = apply(&mut state, Action::ResolveChoice { selection });

    assert!(state.pending_choice.is_none(), "the choice must close");
    assert_eq!(
        state.player.discard.len(),
        4,
        "the duplicated index must not discard twice"
    );
    assert_eq!(
        state.player.draw.len(),
        6 - 4,
        "draw exactly one per ACTUAL discard — never list-length (the C# \
         DiscardAndDraw count includes the duplicate only because the \
         headless driver fed it one; the real select screen cannot)"
    );
    assert_eq!(
        state.player.hand.len(),
        1 + 4,
        "kept card + one drawn per actual discard"
    );
    assert!(
        state.player.hand.contains(&mk_uid(7005)),
        "the unpicked option (index 4) stays in hand"
    );
}

