fn push_card_of_type(
    state: &mut CombatState,
    card_type: crate::cards::CardType,
    cost: i8,
) -> crate::CardUid {
    use crate::cards::{CardId, TargetType};
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let uid = crate::CardUid::new(raw).expect("non-zero");
    state.cards.push(crate::Card {
        uid,
        card_id: CardId::StrikeIronclad,
        cost,
        card_type,
        target_type: TargetType::None,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        combat_vars: crate::cards::CombatVars::new(),
        enchantments: crate::cards::CardEnchantments::new(),
        tags: crate::cards::CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    uid
}

