/// Spending ≥2 energy grants the +4 (unpowered) block — gated on energy
/// ACTUALLY paid (C# `cardPlay.Resources.EnergyValue`), threaded via
/// `CardEventCtx::energy_spent`.
#[test]
#[serial_test::serial(global_registry)]
fn intimidating_helmet_grants_block_at_energy_threshold() {
    install_default_registry();
    let mut state = state_with_intimidating_helmet();
    let uid = push_card_of_type(&mut state, crate::cards::CardType::Attack, 2);
    let ctx = CardEventCtx {
        card_id: state.cards[0].card_id,
        card_uid: Some(uid),
        target: None,
        card_tags: crate::cards::CardTags::NONE,
        energy_spent: 2,
    };
    let result = dispatch_before_card_played(&mut state, &ctx);
    assert_eq!(result, EffectResult::Resolved);
    assert_eq!(state.player.block, INTIMIDATING_HELMET_BLOCK);
}

/// Spending <2 energy grants nothing, even when the card's printed cost is
