// Bead `sts2-rs-zdch1`: per-handler smoke harness — pins
// EffectResult::Resolved on the most-likely-to-silently-regress
// listener handlers. A refactor that swaps Resolved for
// NotImplemented (or vice versa) on any of these handlers would
// turn the listener into a no-op without breaking any of the
// existing semantic-assertion tests; this harness catches that
// regression class explicitly. See bead body for the roster
// selection rationale.
// -----------------------------------------------------------------

/// Macro: assert that with `RelicKind::$kind` in player_relics,
/// the `$dispatch` channel returns `EffectResult::Resolved`. Used
/// for cheap "listener registered + fires" coverage; semantic
/// assertions live on per-relic tests above.
macro_rules! relic_listener_resolves {
    ($name:ident, $kind:ident, $dispatch:expr) => {
        #[test]
        fn $name() {
            ensure_installed();
            let mut state = fresh_state_with_player(80, 50);
            give_player_relic(&mut state, RelicKind::$kind);
            let result = $dispatch(&mut state);
            assert_eq!(
                result,
                EffectResult::Resolved,
                "listener for RelicKind::{} must resolve once \
                     ensure_installed has run and the relic is owned",
                stringify!($kind),
            );
        }
    };
}

relic_listener_resolves!(
    zdch1_meat_on_the_bone_resolves_after_victory,
    MeatOnTheBone,
    dispatch_after_combat_victory
);
relic_listener_resolves!(
    zdch1_black_blood_resolves_after_victory,
    BlackBlood,
    dispatch_after_combat_victory
);
relic_listener_resolves!(
    zdch1_anchor_resolves_before_combat_start,
    Anchor,
    dispatch_before_combat_start
);
relic_listener_resolves!(
    zdch1_fake_anchor_resolves_before_combat_start,
    FakeAnchor,
    dispatch_before_combat_start
);
relic_listener_resolves!(
    zdch1_bronze_scales_resolves_before_combat_start,
    BronzeScales,
    dispatch_before_combat_start
);
