/// BagOfMarbles: round-1 player-side-turn-start fan-out applies
/// Vulnerable +1 to **every** alive enemy in `enemy_uids` order.
/// Python pin:
/// `sts2-rl-agent@01c094d:sts2_env/relics/uncommon.py::BagOfMarbles`.
/// Asserts the multi-target ordering rather than just dispatch
/// reachability — Python iterates `combat.alive_monsters` which the
/// Rust port mirrors via the `enemy_uids` filter + alive check.
#[test]
#[serial_test::serial(global_registry)]
fn bag_of_marbles_applies_vulnerable_to_all_alive_enemies_in_order() {
    use std::num::NonZeroU32;
    ensure_installed();

    let mut state = CombatState::default();
    let player_uid = CreatureUid::new(1).unwrap();
    let enemy_a = CreatureUid::new(2).unwrap();
    let enemy_b = CreatureUid::new(3).unwrap();
    let enemy_dead = CreatureUid::new(4).unwrap();
    for (uid, hp) in [
        (player_uid, 80_i32),
        (enemy_a, 50),
        (enemy_b, 50),
        (enemy_dead, 0),
    ] {
        state.creatures.push(crate::Creature {
            id: uid.0,
            current_hp: hp,
            max_hp: hp.max(1),
            block: 0,
            powers: smallvec::SmallVec::new(),
            species: None,
            intent: None,
            intent_history: crate::IntentHistory::default(),
            monster_id: crate::MonsterId(""),
            ai: None,
        });
    }
    state.player.creature_uid = Some(player_uid);
    state.player.max_hp = 80;
    state.player.current_hp = 80;
    state.round = 1;
    // Order matters — the dispatch must iterate in this order. Add
    // a dead enemy in the middle to confirm the alive filter holds.
    state.enemy_uids.push(enemy_a);
    state.enemy_uids.push(enemy_dead);
    state.enemy_uids.push(enemy_b);

    state.relics.push(crate::Relic {
        id: NonZeroU32::new(1).unwrap(),
        kind: RelicKind::BagOfMarbles,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });

    let result = dispatch_before_side_turn_start(&mut state, crate::Side::Player);
    assert_eq!(result, EffectResult::Resolved);
    assert_eq!(
        enemy_power_amount(&state, enemy_a, PowerKind::Vulnerable),
        1,
        "alive enemy_a got Vulnerable +1"
    );
    assert_eq!(
        enemy_power_amount(&state, enemy_b, PowerKind::Vulnerable),
        1,
        "alive enemy_b got Vulnerable +1"
    );
    assert_eq!(
        enemy_power_amount(&state, enemy_dead, PowerKind::Vulnerable),
        0,
        "dead enemy SKIPPED — alive filter must hold"
    );
}

