/// Order-sensitive multi-relic fan-out: Anchor + BurningBlood
/// both on the player, with Anchor firing at combat start and
/// BurningBlood at combat victory. Asserts both observable state
/// mutations land in the expected hooks (block from Anchor; HP
/// gained from BurningBlood) without interfering with each other.
/// The bead's "order-sensitive hook resolution" point is that
/// these two relics fire on **different** hooks
/// (`before_combat_start` vs `after_combat_victory`) and must not
/// cross-talk; this test pins that independence.
#[test]
#[serial_test::serial(global_registry)]
fn combat_start_and_victory_relic_fan_out_orders_anchor_then_burning_blood() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 50);
    give_player_relic(&mut state, RelicKind::Anchor);
    give_player_relic(&mut state, RelicKind::BurningBlood);

    // before_combat_start: Anchor fires (+10 block), BurningBlood
    // is a no-op on this channel (it's an after-victory hook).
    let r1 = dispatch_before_combat_start(&mut state);
    assert_eq!(r1, EffectResult::Resolved);
    assert_eq!(state.player.block, 10, "Anchor +10");
    assert_eq!(
        state.player.current_hp, 50,
        "BurningBlood does NOT fire at combat start"
    );

    // after_combat_victory: BurningBlood fires (+6 HP), Anchor
    // is a no-op on this channel.
    let r2 = dispatch_after_combat_victory(&mut state);
    assert_eq!(r2, EffectResult::Resolved);
    assert_eq!(state.player.current_hp, 56, "BurningBlood HEAL=6");
    assert_eq!(
        state.player.block, 10,
        "Anchor's combat-start block was NOT clobbered by victory hook"
    );
}

#[cfg(test)]
mod freeze_guard {
    use super::super::channels::*;
    use super::super::ensure_installed;
    use crate::relics::RelicId;

    /// `freeze_all_channels()` must freeze every hot relic hook channel so the
    /// dispatch read path takes the cheap `OnceLock` slice instead of the
    /// `ArcSwap` debt-slot dance (bead sts2-rs-05mjm). A channel missing from
    /// it is still *correct* (it falls back to `ArcSwap`), but silently loses
    /// the perf win — this guards the per-dispatch hot set.
    ///
    /// The freeze belongs to the CONTENT installer, which registers its pools
    /// after this crate's installer; the core installer alone must leave the
    /// channels unfrozen (M02). The test also proves the probe is not vacuous:
    /// a registration after the freeze — what the content pools did while the
    /// core installer froze — must read as un-frozen, which is what
    /// `sts2-content`'s `every_channel_frozen_after_content_install` relies on.
    #[test]
    fn hot_channels_frozen_after_install() {
        ensure_installed();
        assert!(
            !all_channels_frozen(),
            "the core installer must leave the freeze to the content installer"
        );
        freeze_all_channels();
        assert!(all_channels_frozen());
        assert!(registry_after_card_played().is_frozen());
        assert!(registry_before_card_played().is_frozen());
        assert!(registry_after_damage_received().is_frozen());
        assert!(registry_after_damage_given().is_frozen());
        assert!(registry_modify_damage_additive().is_frozen());
        assert!(registry_modify_damage_multiplicative().is_frozen());
        assert!(registry_modify_hp_lost().is_frozen());
        assert!(registry_after_block_gained().is_frozen());
        assert!(registry_after_block_cleared().is_frozen());
        assert!(registry_before_turn_end().is_frozen());
        assert!(registry_after_turn_end().is_frozen());
        assert!(registry_after_side_turn_start().is_frozen());
        assert!(registry_before_side_turn_start().is_frozen());
        assert!(registry_after_player_turn_start().is_frozen());
        assert!(registry_should_clear_block().is_frozen());

        // Re-register an existing handler unchanged (what a second, unguarded
        // content install does): the listener set is identical, but the
        // channel must report that it left the frozen path.
        let divine_right = lookup_after_side_turn_start(RelicId::DivineRight)
            .expect("DivineRight is a core after_side_turn_start listener");
        register_after_side_turn_start(RelicId::DivineRight, divine_right);
        assert!(!registry_after_side_turn_start().is_frozen());
        assert!(!all_channels_frozen());
        assert!(registry_after_card_played().is_frozen());
    }
}

