/// `TheBoot` (v0.107.1) now floors **Osty**-dealt powered attacks too.
/// An Osty powered attack of 3 unblocked HP is bumped to 5; ≥5 is left
/// alone.
#[test]
#[serial_test::serial(global_registry)]
fn the_boot_floors_osty_powered_attack() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::TheBoot);
    let _ = state.summon_osty(1);
    let osty_uid = state
        .creatures
        .iter()
        .find(|c| c.species == Some(crate::MonsterKind::Osty))
        .expect("Osty present")
        .id;
    let enemy = push_enemy(&mut state, 7, 50);
    let ctx = ModifyHpLostCtx {
        target: enemy,
        dealer: Some(crate::CreatureUid(osty_uid)),
        props: crate::hooks::ValueProps::MOVE,
    };
    assert_eq!(
        dispatch_modify_hp_lost(&state, &ctx, 3),
        5,
        "Osty powered attack floored to 5"
    );
    assert_eq!(dispatch_modify_hp_lost(&state, &ctx, 7), 7, "≥5 unchanged");
}

