/// `InfusedCore` (v0.107.1) makes Lightning orb values deal +1: a
/// Lightning passive tick deals `3 + 1 = 4` to the lone enemy with the
/// relic, vs `3` without it.
#[test]
#[serial_test::serial(global_registry)]
fn infused_core_lightning_orb_plus_one() {
    ensure_installed();
    // Control: no InfusedCore → Lightning passive deals 3.
    let mut ctrl = fresh_state_with_player(70, 70);
    ctrl.player.character = Some(crate::potions::CharacterId::Defect);
    ctrl.player.orbs = crate::orbs::OrbSlots::with_default_capacity();
    let e0 = push_enemy(&mut ctrl, 7, 50);
    crate::orbs::channel_orb(&mut ctrl, crate::orbs::Orb::lightning());
    crate::orbs::passive_tick(&mut ctrl);
    let ctrl_dmg = 50
        - ctrl
            .creatures
            .iter()
            .find(|c| c.id == e0.0)
            .unwrap()
            .current_hp;
    assert_eq!(ctrl_dmg, 3, "baseline Lightning passive = 3");

    // With InfusedCore → 4.
    let mut state = fresh_state_with_player(70, 70);
    state.player.character = Some(crate::potions::CharacterId::Defect);
    state.player.orbs = crate::orbs::OrbSlots::with_default_capacity();
    give_player_relic(&mut state, RelicKind::InfusedCore);
    let e1 = push_enemy(&mut state, 7, 50);
    crate::orbs::channel_orb(&mut state, crate::orbs::Orb::lightning());
    crate::orbs::passive_tick(&mut state);
    let dmg = 50
        - state
            .creatures
            .iter()
            .find(|c| c.id == e1.0)
            .unwrap()
            .current_hp;
    assert_eq!(dmg, 4, "InfusedCore Lightning passive = 3 + 1");
}

/// `MummifiedHand` (v0.107.1 multi-pool) frees a hand card on a Power
/// play; the common case (a 1-cost card in hand) still frees it.
#[test]
#[serial_test::serial(global_registry)]
fn mummified_hand_frees_favorable_hand_card() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MummifiedHand);
    // A 1-cost (favorable + currently costing) card in hand. Card uids
    // must equal their `state.cards` index + 1 — `set_card_var` indexes
    // positionally — so push them in uid order starting at 1.
    let hand_card = push_card(&mut state, 1, crate::cards::CardType::Skill);
    state.player.hand.push(hand_card);
    // The played Power.
    let power = push_card(&mut state, 2, crate::cards::CardType::Power);
    let _ = dispatch_after_card_played(&mut state, &make_card_ctx(power));
    let freed = state
        .cards
        .iter()
        .find(|c| c.uid == hand_card)
        .unwrap()
        .combat_var(crate::cards::VarKey::FreeThisTurn);
    assert_eq!(freed, 1, "the 1-cost hand card was made free this turn");
}

/// `MummifiedHand` multi-pool fallback: when no hand card currently
/// costs energy (all 0-cost), v0.107.1 still frees a card via the
/// full-hand pool (4) — the old single-pool port returned without
/// touching any card.
#[test]
#[serial_test::serial(global_registry)]
fn mummified_hand_full_hand_fallback_when_nothing_costs() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::MummifiedHand);
    // Card uids must equal their `state.cards` index + 1 (positional
    // `set_card_var`): push in uid order starting at 1.
    let hand_card = push_card(&mut state, 1, crate::cards::CardType::Skill);
    // Zero-cost card: not favorable, not costing.
    state
        .cards
        .iter_mut()
        .find(|c| c.uid == hand_card)
        .unwrap()
        .cost = 0;
    state.player.hand.push(hand_card);
    let power = push_card(&mut state, 2, crate::cards::CardType::Power);
    let result = dispatch_after_card_played(&mut state, &make_card_ctx(power));
    assert_eq!(result, EffectResult::Resolved, "fallback pool still fires");
    let freed = state
        .cards
        .iter()
        .find(|c| c.uid == hand_card)
        .unwrap()
        .combat_var(crate::cards::VarKey::FreeThisTurn);
    assert_eq!(freed, 1, "the 0-cost card is freed via the full-hand pool");
}

/// `Bookmark` (v0.107.1) reduces the cost of exactly ONE retained
/// (post-flush hand) card by 1, picked via `CombatCardSelection`. With
/// two eligible 2-cost cards, exactly one ends at cost 1.
#[test]
#[serial_test::serial(global_registry)]
fn bookmark_reduces_one_retained_card_cost() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::Bookmark);
    let a = push_card(&mut state, 80, crate::cards::CardType::Attack);
    let b = push_card(&mut state, 81, crate::cards::CardType::Attack);
    for uid in [a, b] {
        state.cards.iter_mut().find(|c| c.uid == uid).unwrap().cost = 2;
        state.player.hand.push(uid);
    }
    after_flush_bookmark(&mut state);
    // Local cost (`GetWithModifiers(Local)`): printed cost minus the
    // until-played bank. (`effective_card_cost` indexes `cards` by uid, which
    // these sparse test uids do not satisfy.)
    let local = |state: &CombatState, uid| {
        let c = state.cards.iter().find(|c| c.uid == uid).unwrap();
        i32::from(c.cost) - c.combat_var(crate::cards::VarKey::CostReductionUntilPlayed)
    };
    let cost_a = local(&state, a);
    let cost_b = local(&state, b);
    assert_eq!(
        cost_a + cost_b,
        3,
        "exactly one of the two retained cards lost 1 cost (2+2 → 1+2)"
    );
    assert!(
        (cost_a == 1 && cost_b == 2) || (cost_a == 2 && cost_b == 1),
        "one card at 1, the other still at 2 (got {cost_a},{cost_b})"
    );
    // C# `AddUntilPlayed(-1)`: the discount is a `WhenPlayed` modifier, so the
    // printed cost survives and playing the card retires it
    // (`AfterCardPlayedCleanup`).
    let reduced = if cost_a == 1 { a } else { b };
    assert_eq!(
        state.cards.iter().find(|c| c.uid == reduced).unwrap().cost,
        2
    );
    state.restore_wire_cost_expiring_on_play(reduced);
    assert_eq!(local(&state, reduced), 2);
}

/// C# `Hook.AfterFlush` (Bookmark) runs before `EndOfTurnCleanup`
/// (CombatManager.cs:1347-1349): a retained card that is free this turn still
/// has local cost 0, so it is not eligible, and Bookmark does not roll. Rust
/// ran it as an `AfterTurnEnd` relic after the cleanup had cleared
/// FreeThisTurn (loadout Necrobinder v0.107.1 2032).
#[test]
#[serial_test::serial(global_registry)]
fn bookmark_runs_before_the_turn_cleanup_clears_free_this_turn() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    let _ = push_enemy(&mut state, 50, 40);
    give_player_relic(&mut state, RelicKind::Bookmark);
    let a = push_card(&mut state, 80, crate::cards::CardType::Attack);
    {
        let card = state.cards.iter_mut().find(|c| c.uid == a).unwrap();
        card.cost = 2;
        card.set_combat_var(crate::cards::VarKey::FreeThisTurn, 1);
    }
    state.player.hand.push(a);
    state.player.retain_this_turn.push(a);
    let rng_before = state.run_rng.combat_card_selection.clone();
    state.phase = crate::CombatPhase::PlayerEndTurnPhaseOne;
    let _ = crate::combat_loop::end_player_turn_phase_two(&mut state);
    let card = state.cards.iter().find(|c| c.uid == a).unwrap();
    assert!(state.player.hand.contains(&a), "retained");
    assert_eq!(card.combat_var(crate::cards::VarKey::FreeThisTurn), 0);
    assert_eq!(
        card.combat_var(crate::cards::VarKey::CostReductionUntilPlayed),
        0,
        "the free card was not eligible"
    );
    assert_eq!(state.run_rng.combat_card_selection, rng_before, "no roll");
}

/// A lethal hit takes the Red Skull owner to 0 HP and FairyInABottle revives
/// them at 30%. C# probes Red Skull at 0 HP first (its `+3` Strength apply is
/// refused while DieForYou makes every corpse unhittable,
/// DieForYouPower.cs:35, but `StrengthApplied` is set), so the revive adds
/// nothing. Without DieForYou the +3 lands (loadout Necrobinder v0.107.1 2035).
#[test]
#[serial_test::serial(global_registry)]
fn red_skull_fairy_revive_gains_no_strength_while_die_for_you_lives() {
    for die_for_you in [true, false] {
        ensure_installed();
        let mut state = fresh_state_with_player(100, 0);
        state.sync_creature_current_hp_from_player();
        give_player_relic(&mut state, RelicKind::RedSkull);
        state.player.potion_slots = 3;
        assert!(state
            .player
            .add_potion_first_free_slot(crate::potions::PotionKind::FairyInABottle));
        if die_for_you {
            state.powers.push(crate::Power {
                id: NonZeroU32::new(9002).unwrap(),
                kind: crate::PowerKind::DieForYou,
                amount: 1,
                counter: 0,
                applier: None,
                skip_next_tick: false,
            });
        }
        assert!(crate::combat_loop::try_fairy_in_a_bottle_prevent_death(
            &mut state
        ));
        assert_eq!(state.player.current_hp, 30);
        let strength = state.player_power_amount(crate::PowerKind::Strength);
        let expected = if die_for_you { 0 } else { 3 };
        assert_eq!(strength, expected, "die_for_you={die_for_you}");
        let counter = state
            .relics
            .iter()
            .find(|r| r.kind == RelicKind::RedSkull)
            .map_or(-1, |r| r.counter);
        assert_eq!(counter, 1, "StrengthApplied either way");
    }
}

