// ---------------------------------------------------------------------------
// ToyBox melt (C# `RelicModel.IsMelted`) — a melted relic stays in the
// inventory but is filtered out of EVERY hook dispatch
// (`MegaCrit.Sts2.Core.Combat/CombatState.cs:130-137`,
// `MegaCrit.Sts2.Core.Runs/RunState.cs:148`).
// ---------------------------------------------------------------------------

/// Melt the (single) relic of `kind` the player owns.
fn melt_player_relic(state: &mut CombatState, kind: RelicKind) {
    let idx = state
        .relics
        .iter()
        .position(|r| r.kind == kind)
        .expect("relic to melt");
    state.relics[idx].is_wax = true;
    state.relics.set_melted(idx, true);
}

/// `StrikeDummy` adds +3 to a Strike attack while live, and NOTHING once
/// melted — the mirror bug that let ToyBox seeds (1001/1018/1019) keep
/// applying relics the world had disabled.
#[test]
#[serial_test::serial(global_registry)]
fn melted_strike_dummy_stops_adding_strike_damage() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::StrikeDummy);
    let player_uid = state.player.creature_uid.expect("player mirror");

    // A Strike-tagged ATTACK in the arena — StrikeDummy re-reads the card
    // out of `state.cards` to check the tag.
    let uid = push_card(&mut state, 77, crate::cards::CardType::Attack);
    {
        let c = state.cards.iter_mut().find(|c| c.uid == uid).unwrap();
        c.card_id = crate::cards::CardId::StrikeIronclad;
        c.tags = crate::cards::CardTags::one(crate::cards::CardTag::Strike);
    }
    let ctx = ModifyDamageCtx {
        dealer: Some(player_uid),
        target: fake_target(),
        base_damage: 6,
        props: crate::hooks::ValueProps::MOVE,
        card: Some(crate::cards::CardId::StrikeIronclad),
        card_uid: Some(uid),
    };

    assert_eq!(
        on_modify_damage_additive_strike_dummy(&state, &ctx),
        3,
        "unmelted StrikeDummy adds +3"
    );

    melt_player_relic(&mut state, RelicKind::StrikeDummy);
    assert_eq!(
        on_modify_damage_additive_strike_dummy(&state, &ctx),
        0,
        "melted StrikeDummy contributes nothing"
    );
    assert_eq!(
        state.relics.len(),
        1,
        "melting does NOT remove the relic from the inventory"
    );
}

/// A melted `SturdyClamp` no longer vetoes the turn-start block clear —
/// the `should_*` predicate registries respect the melt filter too.
#[test]
#[serial_test::serial(global_registry)]
fn melted_sturdy_clamp_allows_block_clear() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::SturdyClamp);
    state.side = Side::Player;
    let ctx = crate::hooks::BlockClearedCtx::default();

    assert!(
        !on_should_clear_block_sturdy_clamp(&state, &ctx),
        "live SturdyClamp suppresses the clear"
    );
    assert!(
        !dispatch_should_clear_block(&state, &ctx),
        "…and the dispatcher agrees"
    );

    melt_player_relic(&mut state, RelicKind::SturdyClamp);
    assert!(
        on_should_clear_block_sturdy_clamp(&state, &ctx),
        "melted SturdyClamp permits the clear"
    );
    assert!(
        dispatch_should_clear_block(&state, &ctx),
        "…and so does the dispatcher"
    );
}

/// The melt filter lives at the ownership predicate every listener shares,
/// and at the listener-enumeration choke point `iter_relic_listeners`.
#[test]
fn melted_relic_is_unowned_and_unlisted() {
    let mut state = fresh_state_with_player(80, 80);
    give_player_relic(&mut state, RelicKind::Vajra);
    give_player_relic(&mut state, RelicKind::Akabeko);
    melt_player_relic(&mut state, RelicKind::Vajra);

    assert!(!player_owns_relic(&state, RelicKind::Vajra));
    assert!(player_owns_relic(&state, RelicKind::Akabeko));
    assert_eq!(
        crate::hooks::iter_relic_listeners(&state).count(),
        1,
        "only the unmelted relic is a hook listener"
    );
    assert_eq!(state.relics.len(), 2, "both relics still equipped");
}

/// C# `Hook.AfterCardPlayed` walks `IterateHookListeners()`
/// (`CombatState.cs:115-131`): the player's powers BEFORE the player's relics.
/// So an armed Serpent Form's random hit draws `CombatTargets` FIRST and
/// Kusarigama's 3rd-attack hit draws second. Silent full-tier seed:5469 (Rust
/// fired the relic bus first, swapping the 4 and the 6 between two enemies).
#[test]
#[serial_test::serial(global_registry)]
fn serpent_form_hit_draws_combat_targets_before_kusarigama() {
    ensure_installed();
    let mut state = fresh_state_with_player(70, 70);
    give_player_relic(&mut state, RelicKind::Kusarigama);
    let e0 = push_enemy(&mut state, 820, 30);
    let e1 = push_enemy(&mut state, 821, 30);
    set_kusarigama_counter(&mut state, 2);
    // Serpent Form(4), armed with its before-play amount snapshot.
    let pid = NonZeroU32::new(u32::try_from(state.powers.len()).expect("fits") + 1).expect("nz");
    state.powers.push(crate::Power {
        id: pid,
        kind: crate::PowerKind::SerpentForm,
        amount: 4,
        counter: 4,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(crate::PowerUid(pid));
    // Advance the stream until its next two 2-way picks differ, so the
    // listener order is observable.
    let (first, second) = loop {
        let mut probe = state.run_rng.combat_targets.clone();
        let a = probe.next_int_exclusive(0, 2);
        let b = probe.next_int_exclusive(0, 2);
        if a != b {
            break (a, b);
        }
        let _ = state.run_rng.combat_targets.next_int_exclusive(0, 2);
    };
    let uid = push_card(&mut state, 820, crate::cards::CardType::Attack);
    let hook_ctx = crate::hooks::CardCtx {
        card_uid: Some(uid),
        card_type: Some(crate::cards::CardType::Attack),
        ..crate::hooks::CardCtx::default()
    };
    crate::combat_loop::dispatch_after_card_played_buses(
        &mut state,
        &make_card_ctx(uid),
        &hook_ctx,
    );
    let hp = |u: CreatureUid| {
        state
            .creatures
            .iter()
            .find(|c| c.id == u.0)
            .map(|c| c.current_hp)
            .unwrap()
    };
    let enemies = [e0, e1];
    assert_eq!(
        hp(enemies[first as usize]),
        26,
        "1st CombatTargets pick = Serpent Form's 4"
    );
    assert_eq!(
        hp(enemies[second as usize]),
        24,
        "2nd CombatTargets pick = Kusarigama's 6"
    );
}

/// C# `LunarPastry.AfterSideTurnEnd` gains its star through
/// `PlayerCmd.GainStars`, which fires `Hook.AfterStarsGained`: Black Hole
/// deals its `Amount` to every enemy (loadout Regent 1020).
#[test]
fn lunar_pastry_star_triggers_black_hole() {
    let mut state = CombatState::default();
    state.player.current_hp = 50;
    state.relics.push(crate::Relic {
        id: std::num::NonZeroU32::new(1).expect("nz"),
        kind: crate::RelicKind::LunarPastry,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let pid = std::num::NonZeroU32::new(1).expect("nz");
    state.powers.push(crate::Power {
        id: pid,
        kind: crate::PowerKind::BlackHole,
        amount: 3,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(crate::PowerUid(pid));
    let enemy = state.spawn_enemy(crate::MonsterKind::Nibbit);
    let hp = |s: &CombatState| {
        s.creatures
            .iter()
            .find(|c| c.id == enemy.0)
            .map(|c| c.current_hp)
            .expect("enemy")
    };
    let before = hp(&state);
    assert_eq!(
        on_after_turn_end_lunar_pastry(&mut state, Side::Player),
        EffectResult::Resolved
    );
    assert_eq!(state.player.stars, 1);
    assert_eq!(state.player.stars_gained_this_turn, 1);
    assert_eq!(
        hp(&state),
        before - 3,
        "Black Hole fires on the gained star"
    );
}
